    private void renderAiChatArchivePage() {
        inAiAnalysisPage = true;
        updateFab();
        content.removeAllViews();
        ScrollView scroll = pageScroll();
        scroll.setTag("ai_chat_archive");
        LinearLayout page = basePage();
        scroll.addView(page);
        content.addView(scroll);

        LinearLayout top = row(Gravity.CENTER_VERTICAL);
        TextView back = label("‹", 38, Color.rgb(34, 34, 34), true);
        back.setGravity(Gravity.CENTER);
        back.setBackground(surfaceRound(dp(25)));
        attachPressAnimation(back);
        back.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                closeAiAnalysisPage();
            }
        });
        top.addView(back, new LinearLayout.LayoutParams(dp(52), dp(52)));
        TextView title = label("历史聊天", 30, Color.rgb(28, 28, 30), true);
        title.setPadding(dp(14), 0, 0, 0);
        top.addView(title, new LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1));
        installStickyHeader(scroll, page, top);

        TextView hint = label("点开某一天可以查看当时的聊天记录，历史记录只读，今天仍在餐饮分析页继续聊天。", 14,
                Color.rgb(116, 122, 130), false);
        hint.setPadding(0, dp(12), 0, dp(12));
        hint.setLineSpacing(dp(2), 1.05f);
        page.addView(hint);

        List<String> dates = aiChatDates();
        if (dates.isEmpty()) {
            page.addView(emptyState("还没有聊天记录", "和餐饮分析聊过的问题会收在这里。", "☁"));
        } else {
            for (final String date : dates) {
                JSONArray chat = optObj(days, date).optJSONArray("aiChat");
                int count = chat == null ? 0 : chat.length();
                page.addView(settingRow(displayDate(date), count + "条聊天", "☰", accent, new View.OnClickListener() {
                    @Override
                    public void onClick(View v) {
                        smoothContentSwap(()->renderAiChatReadOnlyPage(date),1f);
                    }
                }));
            }
        }
        page.addView(space(dp(120)));
        animateIn(page);
    }

    private List<String> aiChatDates() {
        List<String> result = new ArrayList<String>();
        JSONArray names = days.names();
        if (names == null) {
            return result;
        }
        for (int i = 0; i < names.length(); i++) {
            String date = names.optString(i);
            JSONArray chat = optObj(days, date).optJSONArray("aiChat");
            if (chat != null && chat.length() > 0) {
                result.add(date);
            }
        }
        Collections.sort(result, new Comparator<String>() {
            @Override
            public int compare(String a, String b) {
                return b.compareTo(a);
            }
        });
        return result;
    }

    private void renderAiChatReadOnlyPage(final String date) {
        content.removeAllViews();
        ScrollView scroll = pageScroll();
        scroll.setTag("ai_chat_read_only");
        LinearLayout page = basePage();
        scroll.addView(page);
        content.addView(scroll);

        LinearLayout top = row(Gravity.CENTER_VERTICAL);
        TextView back = label("‹", 38, Color.rgb(34, 34, 34), true);
        back.setGravity(Gravity.CENTER);
        back.setBackground(surfaceRound(dp(25)));
        attachPressAnimation(back);
        back.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                closeAiAnalysisPage();
            }
        });
        top.addView(back, new LinearLayout.LayoutParams(dp(52), dp(52)));
        TextView title = label(displayDate(date), 28, Color.rgb(28, 28, 30), true);
        title.setPadding(dp(14), 0, 0, 0);
        top.addView(title, new LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1));
        installStickyHeader(scroll, page, top);

        TextView hint = label("这一天的聊天记录仅可查看，不能重新分析或发送消息。", 14,
                Color.rgb(116, 122, 130), false);
        hint.setPadding(0, dp(12), 0, dp(10));
        page.addView(hint);
        JSONArray chat = optObj(days, date).optJSONArray("aiChat");
        if (chat == null || chat.length() == 0) {
            page.addView(emptyState("没有聊天内容", "这一天暂时没有留下对话。", "☁"));
        } else {
            for (int i = 0; i < chat.length(); i++) {
                JSONObject item = chat.optJSONObject(i);
                if (item == null) {
                    continue;
                }
                page.addView(aiChatBubble(item.optString("role", "assistant"),
                        item.optString("text", "")));
            }
        }
        page.addView(space(dp(120)));
        animateIn(page);
    }

