    private View commonFoodCaloriesView() {
        LinearLayout card = new LinearLayout(this);
        card.setOrientation(LinearLayout.VERTICAL);
        card.setPadding(dp(12), dp(12), dp(12), dp(14));
        card.setBackground(round(nightDecoration() ? Color.rgb(31, 32, 36) : Color.rgb(247, 249, 252),
                dp(18), surfaceStrokeColor(), nightDecoration() ? dp(1) : 0));
        LinearLayout.LayoutParams cardLp = new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
        cardLp.topMargin = dp(10);
        card.setLayoutParams(cardLp);

        card.addView(label("常见食物热量", 16, Color.rgb(32, 34, 38), true));
        TextView note = label("以下为每100克（饮品按每100毫升）的近似热量，烹饪用油、配方和品牌会让结果变化。", 11,
                Color.rgb(118, 122, 130), false);
        note.setPadding(0, dp(5), 0, dp(8));
        note.setLineSpacing(dp(2), 1.05f);
        card.addView(note);

        String category = "";
        LinearLayout pair = null;
        int column = 0;
        for (String item : COMMON_FOOD_CALORIES) {
            String[] parts = item.split("\\|", 3);
            if (parts.length != 3) {
                continue;
            }
            if (!parts[0].equals(category)) {
                if (pair != null && column == 1) {
                    pair.addView(new Space(this), new LinearLayout.LayoutParams(0, dp(44), 1));
                }
                category = parts[0];
                TextView heading = label(category, 13, Color.rgb(78, 84, 94), true);
                heading.setPadding(dp(2), dp(9), 0, dp(5));
                card.addView(heading);
                pair = null;
                column = 0;
            }
            if (column == 0) {
                pair = row(Gravity.CENTER_VERTICAL);
                card.addView(pair, new LinearLayout.LayoutParams(
                        ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
            }
            TextView cell = label(parts[1] + "\n" + parts[2] + " kcal", 11,
                    Color.rgb(72, 76, 84), false);
            cell.setGravity(Gravity.CENTER_VERTICAL);
            cell.setLineSpacing(0, 1.02f);
            cell.setPadding(dp(9), dp(6), dp(8), dp(6));
            cell.setBackground(round(nightDecoration() ? Color.argb(86, 70, 72, 78)
                    : Color.argb(132, 255, 255, 255), dp(9),
                    nightDecoration() ? Color.argb(42, 255, 255, 255) : Color.argb(34, 110, 118, 132), dp(1)));
            LinearLayout.LayoutParams cellLp = new LinearLayout.LayoutParams(0, dp(44), 1);
            if (column == 1) {
                cellLp.leftMargin = dp(6);
            }
            pair.addView(cell, cellLp);
            column = (column + 1) % 2;
        }
        if (pair != null && column == 1) {
            pair.addView(new Space(this), new LinearLayout.LayoutParams(0, dp(44), 1));
        }

        TextView source = label("参考：国家卫生健康委公开膳食资料、USDA FoodData Central。数值仅作日常估算。", 10,
                Color.rgb(142, 146, 154), false);
        source.setPadding(dp(2), dp(10), 0, 0);
        source.setLineSpacing(dp(2), 1.05f);
        card.addView(source);
        return card;
    }

    private View bmiMatrixTable(String title, int[] heights, int[] weights) {
        LinearLayout box = new LinearLayout(this);
        box.setOrientation(LinearLayout.VERTICAL);
        box.setPadding(0, dp(8), 0, dp(2));
        TextView t = label(title, 13, Color.rgb(76, 82, 92), true);
        t.setPadding(0, 0, 0, dp(5));
        box.addView(t);
        box.addView(bmiMatrixRow(weights, 0, true));
        for (int h : heights) {
            box.addView(bmiMatrixRow(weights, h, false));
        }
        return box;
    }

    private LinearLayout bmiMatrixRow(int[] weights, int height, boolean header) {
        LinearLayout row = row(Gravity.CENTER_VERTICAL);
        row.setPadding(0, 0, 0, dp(2));
        TextView first = label(header ? "身高/体重" : height + "", header ? 7 : 9,
                Color.rgb(72, 78, 88), true);
        first.setGravity(Gravity.CENTER);
        first.setBackground(round(header ? Color.argb(108, 230, 236, 244) : Color.argb(72, 230, 236, 244), dp(4), Color.argb(60, 120, 130, 145), dp(1)));
        row.addView(first, new LinearLayout.LayoutParams(dp(50), dp(28)));
        for (int weight : weights) {
            TextView cell = label(header ? weight + "" : String.format(Locale.CHINA, "%.1f", bmiFor(height, weight)), 8,
                    Color.rgb(46, 52, 60), true);
            cell.setGravity(Gravity.CENTER);
            cell.setBackground(round(header ? Color.argb(98, 236, 240, 246) : bmiCellColor(bmiFor(height, weight)),
                    dp(4), Color.argb(46, 90, 96, 108), dp(1)));
            LinearLayout.LayoutParams lp = new LinearLayout.LayoutParams(0, dp(28), 1);
            lp.leftMargin = dp(2);
            row.addView(cell, lp);
        }
        return row;
    }

    private float bmiFor(int heightCm, int weightKg) {
        float m = heightCm / 100f;
        return weightKg / (m * m);
    }

    private int bmiCellColor(float bmi) {
        if (bmi < 18.5f) {
            return Color.argb(82, 187, 220, 244);
        }
        if (bmi < 24f) {
            return Color.argb(92, 184, 226, 190);
        }
        if (bmi < 28f) {
            return Color.argb(86, 246, 205, 205);
        }
        return Color.argb(98, 244, 145, 145);
    }

