    private void showSetPasswordDialog(final boolean hasExistingPassword) {
        if (activeOverlay != null) closeActiveOverlay(false);

        final FrameLayout overlay = new FrameLayout(this);
        overlay.setBackgroundColor(Color.argb(nightDecoration() ? 118 : 92, 18, 20, 24));
        overlay.setClickable(true);
        activeOverlay = overlay;
        setOverlayBackgroundBlur(true);

        LinearLayout box = new LinearLayout(this);
        box.setOrientation(LinearLayout.VERTICAL);
        box.setPadding(dp(22), dp(20), dp(22), dp(16));
        int glass = nightDecoration() ? Color.argb(222, 38, 40, 46) : Color.argb(214, 255, 255, 255);
        box.setBackground(round(glass, dp(30), adjustAlpha(accent, nightDecoration() ? 82 : 54), dp(1)));
        box.setClickable(true);
        box.setElevation(dp(12));

        box.addView(label(hasExistingPassword ? "修改密码" : "设置密码", 22, Color.rgb(28, 28, 30), true));

        final EditText[] oldPwdHolder = new EditText[1];
        if (hasExistingPassword) {
            TextView oldLabel = label("旧密码", 14, Color.rgb(112, 116, 124), false);
            oldLabel.setPadding(dp(2), dp(14), 0, dp(6));
            box.addView(oldLabel);
            oldPwdHolder[0] = profileEditInput("输入旧密码", true);
            oldPwdHolder[0].setInputType(InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_VARIATION_PASSWORD);
            box.addView(oldPwdHolder[0], new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, dp(52)));
        }

        TextView newLabel = label("新密码", 14, Color.rgb(112, 116, 124), false);
        newLabel.setPadding(dp(2), hasExistingPassword ? dp(6) : dp(14), 0, dp(6));
        box.addView(newLabel);
        final EditText newPwdInput = profileEditInput("请输入新密码（至少4位）", true);
        newPwdInput.setInputType(InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_VARIATION_PASSWORD);
        box.addView(newPwdInput, new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, dp(52)));

        TextView confirmLabel = label("确认密码", 14, Color.rgb(112, 116, 124), false);
        confirmLabel.setPadding(dp(2), dp(6), 0, dp(6));
        box.addView(confirmLabel);
        final EditText confirmPwdInput = profileEditInput("再次输入新密码", true);
        confirmPwdInput.setInputType(InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_VARIATION_PASSWORD);
        box.addView(confirmPwdInput, new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, dp(52)));

        LinearLayout actions = row(Gravity.RIGHT | Gravity.CENTER_VERTICAL);
        actions.setPadding(0, dp(18), 0, 0);
        TextView cancel = dialogButton("取消", Color.rgb(245, 246, 248), Color.rgb(90, 90, 90));
        TextView save = dialogButton("保存", accent, Color.WHITE);
        cancel.setOnClickListener(new View.OnClickListener() { @Override public void onClick(View v) { closeActiveOverlay(true); } });
        save.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                final String oldPwd = (oldPwdHolder[0] != null) ? oldPwdHolder[0].getText().toString().trim() : "";
                final String newPwd = newPwdInput.getText().toString().trim();
                final String confirmPwd = confirmPwdInput.getText().toString().trim();
                if (newPwd.length() < 4) {
                    showSimpleInfoDialog("密码太短", "密码至少需要4个字符");
                    return;
                }
                if (!newPwd.equals(confirmPwd)) {
                    showSimpleInfoDialog("密码不一致", "两次输入的密码不一致，请重新输入");
                    return;
                }
                if (hasExistingPassword && oldPwd.length() == 0) {
                    showSimpleInfoDialog("需要旧密码", "请输入旧密码");
                    return;
                }
                closeActiveOverlay(false);
                new Thread(new Runnable() {
                    @Override
                    public void run() {
                        final CloudResult result = cloudSetPassword(newPwd, hasExistingPassword ? oldPwd : null);
                        runOnUiThread(new Runnable() {
                            @Override
                            public void run() {
                                if (result.ok) {
                                    try {
                                        profile.put("cloudHasPassword", true);
                                        saveProfile();
                                    } catch (JSONException ignored) {}
                                    if (inProfileSettingsPage) renderProfileSettingsPage();
                                    showGlassToast(result.message, Toast.LENGTH_SHORT);
                                } else {
                                    showGlassToast(result.message.length() > 0 ? result.message : "操作失败", Toast.LENGTH_LONG);
                                }
                            }
                        });
                    }
                }).start();
            }
        });
        LinearLayout.LayoutParams cancelLp = new LinearLayout.LayoutParams(dp(78), dp(42));
        cancelLp.rightMargin = dp(10);
        actions.addView(cancel, cancelLp);
        actions.addView(save, new LinearLayout.LayoutParams(dp(78), dp(42)));
        box.addView(actions);

        FrameLayout.LayoutParams boxLp = new FrameLayout.LayoutParams(
                (int) (getResources().getDisplayMetrics().widthPixels * 0.86f),
                ViewGroup.LayoutParams.WRAP_CONTENT);
        boxLp.gravity = Gravity.CENTER;
        overlay.addView(box, boxLp);
        root.addView(overlay, new FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
        overlay.setAlpha(0f);
        box.setAlpha(0f);
        box.setScaleX(0.78f);
        box.setScaleY(0.78f);
        box.setTranslationY(dp(34));
        overlay.animate().alpha(1f).setDuration(180).start();
        box.animate().alpha(1f).scaleX(1f).scaleY(1f).translationY(0f).setDuration(340)
                .setInterpolator(new android.view.animation.DecelerateInterpolator(1.8f)).start();
    }

