    private void renderBookDetail(final String date, boolean animatePage) {
        cancelPendingBookClose();if(!inBookDetail)bookEntryDate=date;
        inBookDetail = true;
        inPreferencesPage = false;
        inPhotoViewer = false;
        bookDetailDate = date;
        updateFab();
        content.removeAllViews();

        FrameLayout host = new FrameLayout(this);
        disableForceDark(host);

        bookDetailSwipeFrame = new BookDetailSwipeFrame(this);
        bookDetailSwipeFrame.setClipChildren(true);
        bookDetailSwipeFrame.setClipToPadding(true);
        disableForceDark(bookDetailSwipeFrame);
        View page = buildBookDetailPage(date, animatePage);
        bookDetailSwipeFrame.setCurrentPage(page, date);
        host.addView(bookDetailSwipeFrame, new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
        installStickyHeader(host, bookDetailSwipeFrame, bookDetailTopBar(date), true);

        content.addView(host, new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
    }

