    private View recycleItemRow(final int index, JSONObject item) {
        LinearLayout row = row(Gravity.CENTER_VERTICAL);
        row.setPadding(dp(14), dp(12), dp(14), dp(12));
        row.setBackground(surfaceRound(dp(18)));
        LinearLayout.LayoutParams rowLp = new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
        rowLp.bottomMargin = dp(10);
        row.setLayoutParams(rowLp);
        row.setClickable(true);
        attachPressAnimation(row);
        row.setOnLongClickListener(new View.OnLongClickListener() {
            @Override
            public boolean onLongClick(View v) {
                showRecycleItemActions(index);
                return true;
            }
        });

        ImageView thumb = new ImageView(this);
        disableForceDark(thumb);
        thumb.setScaleType(ImageView.ScaleType.CENTER_CROP);
        thumb.setBackground(round(nightDecoration() ? Color.rgb(46, 48, 54) : Color.rgb(246, 248, 250), dp(14),
                surfaceStrokeColor(), nightDecoration() ? dp(1) : 0));
        File file = new File(getFilesDir(), item.optString("file", ""));
        if (file.exists()) {
            loadMediaThumbnail(thumb, item.optString("file", ""), dp(56));
        }
        row.addView(thumb, new LinearLayout.LayoutParams(dp(56), dp(56)));

        LinearLayout texts = new LinearLayout(this);
        texts.setOrientation(LinearLayout.VERTICAL);
        texts.setPadding(dp(12), 0, 0, 0);
        String title = item.optString("title", "图片");
        String meal = mealTitle(item.optString("mealKey", ""));
        TextView name = label(meal + " · " + title, 16, Color.rgb(34, 34, 34), true);
        TextView sub = label(displayMonthDay(item.optString("date", "")) + " · " + recycleRemainText(item.optLong("deletedAt", 0)),
                13, nightDecoration() ? Color.rgb(150, 154, 162) : Color.rgb(122, 126, 134), false);
        texts.addView(name);
        texts.addView(sub);
        row.addView(texts, new LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1));
        TextView hint = label("长按", 13, Color.rgb(150, 154, 162), false);
        row.addView(hint);
        return row;
    }

    private String recycleSummary() {
        cleanupRecycleBin();
        int count = recycleBinArray().length();
        return count == 0 ? "空" : count + "项待处理";
    }

    private String recycleRemainText(long deletedAt) {
        long left = Math.max(0, 24L * 60L * 60L * 1000L - (System.currentTimeMillis() - deletedAt));
        long hours = Math.max(1, left / (60L * 60L * 1000L));
        return "约" + hours + "小时后清理";
    }

    private JSONArray recycleBinArray() {
        JSONArray arr = profile == null ? null : profile.optJSONArray("recycleBin");
        if (arr == null) {
            arr = new JSONArray();
            try {
                profile.put("recycleBin", arr);
            } catch (JSONException ignored) {
            }
        }
        return arr;
    }

    private void cleanupRecycleBin() {
        if (profile == null) {
            return;
        }
        JSONArray old = profile.optJSONArray("recycleBin");
        if (old == null || old.length() == 0) {
            return;
        }
        long cutoff = System.currentTimeMillis() - 24L * 60L * 60L * 1000L;
        JSONArray keep = new JSONArray();
        boolean changed = false;
        for (int i = 0; i < old.length(); i++) {
            JSONObject item = old.optJSONObject(i);
            if (item == null) {
                changed = true;
                continue;
            }
            if (item.optLong("deletedAt", System.currentTimeMillis()) < cutoff) {
                deleteRecycleFile(item);
                changed = true;
            } else {
                keep.put(item);
            }
        }
        if (changed) {
            try {
                profile.put("recycleBin", keep);
                saveProfile();
            } catch (JSONException ignored) {
            }
        }
    }

    private void moveMediaToRecycle(String date, String mealKey, String arrayKey, String title, String fileName) {
        try {
            JSONObject item = new JSONObject();
            item.put("date", date);
            item.put("mealKey", mealKey);
            item.put("arrayKey", arrayKey);
            item.put("title", title);
            item.put("file", fileName);
            item.put("deletedAt", System.currentTimeMillis());
            recycleBinArray().put(item);
            saveProfile();
        } catch (JSONException ignored) {
        }
    }

    private void showRecycleItemActions(final int index) {
        final String[] names = {"恢复", "彻底删除", "取消"};
        showChoiceDialog("回收站", names, -1, new ChoiceHandler() {
            @Override
            public void onChoice(int which) {
                if (which == 0) {
                    restoreRecycleItem(index);
                } else if (which == 1) {
                    confirmDeleteRecycleItem(index);
                }
            }
        });
    }

    private void restoreRecycleItem(int index) {
        JSONArray arr = recycleBinArray();
        JSONObject item = arr.optJSONObject(index);
        if (item == null) {
            return;
        }
        String fileName = item.optString("file", "");
        File file = new File(getFilesDir(), fileName);
        if (!file.exists()) {
            removeRecycleAt(index);
            showGlassToast("文件已经不见了", Toast.LENGTH_SHORT);
            rerenderPreservingScroll(new Runnable() {
                @Override
                public void run() {
                    renderRecycleBinPage();
                }
            });
            return;
        }
        try {
            JSONObject meal = optObj(ensureDay(item.optString("date", homeDate())), item.optString("mealKey", "breakfast"));
            String arrayKey = item.optString("arrayKey", "photos");
            JSONArray media = meal.optJSONArray(arrayKey);
            if (media == null) {
                media = new JSONArray();
                meal.put(arrayKey, media);
            }
            boolean exists = false;
            for (int i = 0; i < media.length(); i++) {
                if (fileName.equals(media.optString(i))) {
                    exists = true;
                    break;
                }
            }
            if (!exists) {
                media.put(fileName);
            }
            saveDays();
            removeRecycleAt(index);
            showGlassToast("已恢复", Toast.LENGTH_SHORT);
            NutritionStore.restoreBundle(this, item.optString("date", homeDate()), item.optString("mealKey", "breakfast"), item.optJSONArray("foodItems"));
            days = readJson(DATA_KEY);
            rerenderPreservingScroll(new Runnable() {
                @Override
                public void run() {
                    renderRecycleBinPage();
                }
            });
        } catch (JSONException ignored) {
        }
    }

