    private void deleteAllRecycleItems() {
        JSONArray arr = recycleBinArray();
        for (int i = 0; i < arr.length(); i++) {
            JSONObject item = arr.optJSONObject(i);
            if (item != null) {
                deleteRecycleFile(item);
            }
        }
        try {
            profile.put("recycleBin", new JSONArray());
            saveProfile();
        } catch (JSONException ignored) {
        }
        showGlassToast("回收站已清空", Toast.LENGTH_SHORT);
        rerenderPreservingScroll(new Runnable() {
            @Override
            public void run() {
                renderRecycleBinPage();
            }
        });
    }

    private void deleteAllRecycleFilesSilently() {
        JSONArray arr = recycleBinArray();
        for (int i = 0; i < arr.length(); i++) {
            JSONObject item = arr.optJSONObject(i);
            if (item != null) {
                deleteRecycleFile(item);
            }
        }
        try {
            profile.put("recycleBin", new JSONArray());
            saveProfile();
        } catch (JSONException ignored) {
        }
    }

    private void deleteRecycleFile(JSONObject item) {
        File file = new File(getFilesDir(), safeBackupFileName(item.optString("file", "")));
        if (file.exists() && file.isFile()) {
            file.delete();
        }
        JSONArray foods=item.optJSONArray("foodItems");
        for(int i=0;foods!=null&&i<foods.length();i++){
            JSONObject food=foods.optJSONObject(i);String name=food==null?"":safeBackupFileName(food.optString("cutoutFile"));
            if(name.length()>0 && !referencedMediaFileNames(days).contains(name)) new File(getFilesDir(),name).delete();
        }
    }

    private void removeRecycleAt(int index) {
        JSONArray old = recycleBinArray();
        JSONArray next = new JSONArray();
        for (int i = 0; i < old.length(); i++) {
            if (i != index) {
                JSONObject item = old.optJSONObject(i);
                if (item != null) {
                    next.put(item);
                }
            }
        }
        try {
            profile.put("recycleBin", next);
            saveProfile();
        } catch (JSONException ignored) {
        }
    }


