    private void addHintEditor(final LinearLayout list, final List<EditText> inputs,
                               String prefix, String hint, String value, final Runnable onSave,
                               boolean editableOnCreate) {
        final LinearLayout card = new LinearLayout(this);
        card.setOrientation(LinearLayout.VERTICAL);
        card.setPadding(dp(16), dp(12), dp(16), dp(12));
        card.setBackground(surfaceRound(dp(18)));
        card.setLongClickable(true);
        LinearLayout.LayoutParams cardLp = new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
        cardLp.bottomMargin = dp(10);
        list.addView(card, cardLp);

        LinearLayout titleRow = row(Gravity.CENTER_VERTICAL);
        titleRow.setPadding(0, 0, 0, dp(6));
        TextView title = label(prefix + " " + (inputs.size() + 1), 14, Color.rgb(108, 112, 118), true);
        titleRow.addView(title, new LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1));
        final TextView edit = label("修改", 13, accent, true);
        edit.setGravity(Gravity.CENTER);
        edit.setPadding(dp(10), dp(4), dp(10), dp(4));
        edit.setBackground(round(nightDecoration() ? Color.rgb(36, 38, 42) : accentSoft, dp(12), 0, 0));
        attachPressAnimation(edit);
        titleRow.addView(edit);
        card.addView(titleRow);

        final EditText input = new EditText(this);
        applyGlobalTextTypeface(input, false);
        final boolean[] editing = new boolean[]{editableOnCreate};
        input.setText(stripHintTail(value));
        input.setHint(hint);
        input.setTextSize(scaled(15));
        input.setTextColor(themedTextColor(Color.rgb(40, 40, 40)));
        input.setHintTextColor(themedTextColor(Color.rgb(165, 165, 165)));
        input.setMinLines(2);
        input.setMaxLines(5);
        input.setGravity(Gravity.TOP | Gravity.LEFT);
        input.setSingleLine(false);
        input.setHorizontallyScrolling(false);
        input.setPadding(dp(12), dp(10), dp(12), dp(10));
        input.setBackground(round(nightDecoration() ? Color.rgb(30, 31, 34) : Color.rgb(248, 250, 252),
                dp(14), surfaceStrokeColor(), nightDecoration() ? dp(1) : 0));
        setHintEditorEditable(input, editableOnCreate);
        card.addView(input, new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
        inputs.add(input);

        edit.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                if (!editing[0]) {
                    editing[0] = true;
                    edit.setText("保存");
                    setHintEditorEditable(input, true);
                    focusInput(input);
                    return;
                }
                editing[0] = false;
                edit.setText("修改");
                setHintEditorEditable(input, false);
                hideKeyboard();
                if (onSave != null) {
                    onSave.run();
                }
                showGlassToast("保存成功", Toast.LENGTH_SHORT);
            }
        });
        View.OnLongClickListener deleteListener = new View.OnLongClickListener() {
            @Override
            public boolean onLongClick(View v) {
                showChoiceDialog("这条文案", new String[]{"删除", "取消"}, new ChoiceHandler() {
                    @Override
                    public void onChoice(int which) {
                        if (which == 0) {
                            inputs.remove(input);
                            list.removeView(card);
                            if (onSave != null) {
                                onSave.run();
                            }
                            showGlassToast("已删除", Toast.LENGTH_SHORT);
                        }
                    }
                });
                return true;
            }
        };
        card.setOnLongClickListener(deleteListener);
        edit.setOnLongClickListener(deleteListener);
        if (editableOnCreate) {
            edit.setText("保存");
            focusInput(input);
        }
    }

    private void setHintEditorEditable(EditText input, boolean editable) {
        input.setFocusable(editable);
        input.setFocusableInTouchMode(editable);
        input.setCursorVisible(editable);
        input.setInputType(editable
                ? InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_FLAG_MULTI_LINE | InputType.TYPE_TEXT_FLAG_CAP_SENTENCES
                : InputType.TYPE_NULL);
    }

    private void focusInput(final EditText input) {
        input.postDelayed(new Runnable() {
            @Override
            public void run() {
                forceShowKeyboard(input, true);
            }
        }, 90);
    }

    private void forceShowKeyboard(final EditText input) {
        forceShowKeyboard(input, false);
    }

    private void forceShowKeyboard(final EditText input, final boolean moveCursorToEnd) {
        if (input == null) {
            return;
        }
        input.setFocusable(true);
        input.setFocusableInTouchMode(true);
        input.setCursorVisible(true);
        input.requestFocus();
        input.postDelayed(new Runnable() {
            @Override
            public void run() {
                input.requestFocus();
                if (moveCursorToEnd) {
                    input.setSelection(input.getText().length());
                }
                InputMethodManager imm = (InputMethodManager) getSystemService(INPUT_METHOD_SERVICE);
                if (imm != null) {
                    imm.showSoftInput(input, InputMethodManager.SHOW_FORCED);
                }
            }
        }, 40);
    }


