    private void updateSettingRowSubtitle(View row, String subtitle) {
        if (!(row instanceof ViewGroup)) {
            return;
        }
        TextView target = findTaggedTextView((ViewGroup) row, "subtitle");
        if (target != null) {
            target.setText(subtitle == null ? "" : subtitle);
        }
    }

    private TextView findTaggedTextView(ViewGroup parent, String tag) {
        for (int i = 0; i < parent.getChildCount(); i++) {
            View child = parent.getChildAt(i);
            Object childTag = child.getTag();
            if (tag.equals(childTag) && child instanceof TextView) {
                return (TextView) child;
            }
            if (child instanceof ViewGroup) {
                TextView found = findTaggedTextView((ViewGroup) child, tag);
                if (found != null) {
                    return found;
                }
            }
        }
        return null;
    }

