    private void saveProfileInfoFromDialog(final EditText nameInput, final EditText signatureInput) {
        final String name = nameInput.getText().toString().trim();
        final String signature = signatureInput.getText().toString().trim();
        boolean creating = profile != null && profile.optString("userId", "").length() == 0 && name.length() > 0;
        if (creating && !profile.optBoolean("accountCreatePromptSeen", false)) {
            showCreateAccountConfirmDialog(new Runnable() {
                @Override
                public void run() {
                    try {
                        profile.put("accountCreatePromptSeen", true);
                    } catch (JSONException ignored) {
                    }
                    checkNicknameAndSave(name, signature, true, true);
                }
            });
            return;
        }
        checkNicknameAndSave(name, signature, creating, false);
    }

    private void checkNicknameAndSave(final String name, final String signature, final boolean createAccount, final boolean retryAfterFail) {
        if (!hasCloudIdentity() || name.length() == 0) {
            commitProfileInfo(name, signature, createAccount);
            return;
        }
        final int uid = parseIntSafe(profile.optString("userId", ""));
        new Thread(new Runnable() {
            @Override
            public void run() {
                final CloudResult check = cloudCheckNickname(name, uid);
                runOnUiThread(new Runnable() {
                    @Override
                    public void run() {
                        if (check.ok) {
                            commitProfileInfo(name, signature, createAccount);
                        } else {
                            if (!retryAfterFail) {
                                showSimpleInfoDialog("昵称不可用", check.message.length() > 0 ? check.message : "该用户名已被其他用户使用，请更换昵称");
                            } else {
                                showSimpleInfoDialog("昵称不可用", check.message);
                            }
                        }
                    }
                });
            }
        }).start();
    }

    private void commitProfileInfo(String name, String signature, boolean createAccount) {
        try {
            profile.put("name", name.length() > 0 ? name : "给自己起个名字");
            if (signature.length() > 0) {
                profile.put("signature", signature);
            } else {
                profile.remove("signature");
            }
            saveProfile();
            closeActiveOverlay(false);
            renderCurrent();
            if (createAccount) {
                ensureCloudIdentity(true);
            } else if (hasCloudIdentity()) {
                syncCloudProfile(false);
            }
        } catch (JSONException ignored) {
        }
    }

