    private void closeActiveOverlay(boolean animated) {
        final View overlay = activeOverlay;
        if (overlay == null) {
            clearOverlayEffects();
            return;
        }
        hideKeyboard();
        activeOverlay = null;
        if (!animated) {
            root.removeView(overlay);
            clearOverlayEffects();
            return;
        }
        overlay.animate().cancel();
        overlay.animate()
                .alpha(0f)
                .setDuration(150)
                .withEndAction(new Runnable() {
                    @Override
                    public void run() {
                        try {
                            root.removeView(overlay);
                        } catch (Exception ignored) {
                        }
                        clearOverlayEffects();
                    }
                })
                .start();
    }

    private void clearOverlayEffects() {
        setOverlayBackgroundBlur(false);
    }

    private boolean platformBlurSupported() {
        if (Build.VERSION.SDK_INT < 31) {
            return false;
        }
        String manufacturer = ((Build.MANUFACTURER == null ? "" : Build.MANUFACTURER) + " "
                + (Build.BRAND == null ? "" : Build.BRAND)).toLowerCase(Locale.ROOT);
        return !manufacturer.contains("honor") && !manufacturer.contains("huawei");
    }

    private void setOverlayBackgroundBlur(boolean enabled) {
        if (!platformBlurSupported() || content == null || navHost == null) {
            return;
        }
        try {
            if (enabled) {
                content.setRenderEffect(RenderEffect.createBlurEffect(
                        dp(5), dp(5), Shader.TileMode.CLAMP));
                navHost.setRenderEffect(RenderEffect.createBlurEffect(
                        dp(4), dp(4), Shader.TileMode.CLAMP));
            } else {
                content.setRenderEffect(null);
                navHost.setRenderEffect(null);
            }
        } catch (Throwable ignored) {
            try {
                content.setRenderEffect(null);
                navHost.setRenderEffect(null);
            } catch (Throwable ignoredAgain) {
            }
        }
    }

    private void pickAvatar() {
        Intent intent = new Intent(Intent.ACTION_PICK, MediaStore.Images.Media.EXTERNAL_CONTENT_URI);
        intent.setType("image/*");
        intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);
        try {
            startActivityForResult(intent, REQ_PICK_AVATAR);
        } catch (Exception e) {
            Intent fallback = new Intent(Intent.ACTION_GET_CONTENT);
            fallback.setType("image/*");
            fallback.addCategory(Intent.CATEGORY_OPENABLE);
            try {
                startActivityForResult(Intent.createChooser(fallback, "选择头像"), REQ_PICK_AVATAR);
            } catch (Exception ignored) {
                showGlassToast("没有找到可用的相册", Toast.LENGTH_SHORT);
            }
        }
    }

    @Override
    protected void onActivityResult(int requestCode, int resultCode, Intent data) {
        super.onActivityResult(requestCode, resultCode, data);
        if (requestCode == REQ_PICK_AVATAR && resultCode == RESULT_OK && data != null && data.getData() != null) {
            Uri uri = data.getData();
            try {
                getContentResolver().takePersistableUriPermission(uri, Intent.FLAG_GRANT_READ_URI_PERMISSION);
            } catch (Exception ignored) {
            }
            try {
                Bitmap src = decodeBitmap(uri, 640);
                if (src == null) {
                    showGlassToast("头像读取失败", Toast.LENGTH_SHORT);
                    return;
                }
                Bitmap cropped = centerCrop(src, 360, 360);
                saveBitmap(cropped, new File(getFilesDir(), "avatar.bin"), 88);
                recycleBitmapUnless(src, cropped);
                recycleBitmapUnless(cropped, null);
                showGlassToast("头像已更新", Toast.LENGTH_SHORT);
                renderCurrent();
            } catch (Throwable e) {
                releaseThumbnailMemory();
                showGlassToast("头像保存失败", Toast.LENGTH_SHORT);
            }
        } else if (requestCode == REQ_PICK_MEAL_PHOTO) {
            if (resultCode == RESULT_OK && data != null) {
                importSelectedMealMediaAsync(selectedImageUris(data), false);
            } else {
                finishMealPhotoPickMode(false);
            }
        } else if (requestCode == REQ_PICK_MEAL_STICKER) {
            if (resultCode == RESULT_OK && data != null) {
                importSelectedMealMediaAsync(selectedImageUris(data), true);
            } else {
                finishMealPhotoPickMode(false);
            }
        } else if (requestCode == REQ_RESTORE_BACKUP && resultCode == RESULT_OK && data != null && data.getData() != null) {
            Uri uri = data.getData();
            try {
                getContentResolver().takePersistableUriPermission(uri, Intent.FLAG_GRANT_READ_URI_PERMISSION);
            } catch (Exception ignored) {
            }
            restoreBackupFromUri(uri);
        } else if (requestCode == REQ_INTERNAL_FOOD_CAPTURE) {
            if (resultCode == RESULT_OK && data != null) {
                String returnedDate=data.getStringExtra(FoodCaptureActivity.EXTRA_DATE), returnedMeal=data.getStringExtra(FoodCaptureActivity.EXTRA_MEAL);
                if(returnedDate!=null&&returnedDate.matches("\\d{4}-\\d{2}-\\d{2}"))pendingPhotoDate=returnedDate;
                for(String key:NutritionStore.MEALS)if(key.equals(returnedMeal))pendingPhotoMeal=key;
                importSelectedMealMediaAsync(selectedImageUris(data),false);
            } else finishMealPhotoPickMode(false);
        } else if (requestCode == REQ_TAKE_MEAL_PHOTO) {
            handleMealCameraResult(resultCode, data);
        }
    }

    @Override
    public void onRequestPermissionsResult(int requestCode, String[] permissions, int[] grantResults) {
        super.onRequestPermissionsResult(requestCode, permissions, grantResults);
        if (requestCode != REQ_POST_NOTIFICATIONS || !pendingMealNotificationEnable) {
            return;
        }
        pendingMealNotificationEnable = false;
        boolean granted = grantResults != null && grantResults.length > 0
                && grantResults[0] == PackageManager.PERMISSION_GRANTED;
        if (granted && setProfileBoolean("mealNotificationsEnabled", true)) {
            MealReminderReceiver.ensureScheduled(this);
            showGlassToast("三餐通知已开启", Toast.LENGTH_SHORT);
            if (inMoreSettingsPage) {
                rerenderPreservingScroll(new Runnable() {
                    @Override
                    public void run() {
                        renderMealReminderSettingsPage();
                    }
                });
            }
        } else {
            showSimpleInfoDialog("需要通知权限", "开启系统通知权限后，才能按设定时间提醒你记录三餐。");
        }
    }

    private void handleMealCameraResult(final int resultCode, Intent data) {
        final Uri outputUri = pendingMealCameraUri;
        final String targetDate = pendingPhotoDate;
        final String targetMeal = pendingPhotoMeal;
        final List<String> savedSources = new ArrayList<String>();
        final List<Uri> candidateUris = new ArrayList<Uri>();
        if (outputUri != null) {
            candidateUris.add(outputUri);
        }
        if (data != null && data.getData() != null && !candidateUris.contains(data.getData())) {
            candidateUris.add(data.getData());
        }
        ClipData returnedClip = data == null ? null : data.getClipData();
        if (returnedClip != null) {
            for (int i = 0; i < returnedClip.getItemCount(); i++) {
                Uri returnedUri = returnedClip.getItemAt(i).getUri();
                if (returnedUri != null && !candidateUris.contains(returnedUri)) {
                    candidateUris.add(returnedUri);
                }
            }
        }
        Bitmap preview = null;
        if (data != null && data.getExtras() != null && data.getExtras().get("data") instanceof Bitmap) {
            preview = (Bitmap) data.getExtras().get("data");
        }
        final Bitmap fallbackPreview = preview;
        final int target = 2048;
        Log.i(LOG_TAG, "camera result code=" + resultCode + " output=" + outputUri
                + " candidates=" + candidateUris.size() + " preview=" + (preview != null));
        mealPhotoPickAwaitingResult = true;
        new Thread(new Runnable() {
            @Override
            public void run() {
                Bitmap fullPhoto = null;
                Uri decodedUri = null;
                long[] retryDelays = {0L, 90L, 180L, 320L, 520L};
                if (!candidateUris.isEmpty()) {
                    for (long delay : retryDelays) {
                        if (delay > 0L) {
                            try {
                                Thread.sleep(delay);
                            } catch (InterruptedException interrupted) {
                                Thread.currentThread().interrupt();
                                break;
                            }
                        }
                        for (Uri candidateUri : candidateUris) {
                            fullPhoto = decodeBitmap(candidateUri, target);
                            if (fullPhoto != null && fullPhoto.getWidth() > 0 && fullPhoto.getHeight() > 0) {
                                decodedUri = candidateUri;
                                break;
                            }
                        }
                        if (fullPhoto != null) {
                            break;
                        }
                    }
                }
                Log.i(LOG_TAG, "camera decode uri=" + decodedUri + " bitmap="
                        + (fullPhoto == null ? "null" : fullPhoto.getWidth() + "x" + fullPhoto.getHeight()));
                final Bitmap photo = fullPhoto != null ? fullPhoto : fallbackPreview;
                final boolean accepted = resultCode == RESULT_OK
                        || (outputUri != null && photo != null);
                final boolean saved = accepted && photo != null
                        && saveMealBitmap(targetDate, targetMeal, photo, false, false, savedSources);
                recycleBitmapUnless(photo, null);
                if (fallbackPreview != photo) {
                    recycleBitmapUnless(fallbackPreview, null);
                }
                runOnUiThread(new Runnable() {
                    @Override
                    public void run() {
                        clearPendingMealCameraOutput();
                        if (saved) {
                            showGlassToast("照片已准备，请预览后确认", Toast.LENGTH_SHORT);
                            finishMealPhotoPickMode(true);
                            showFoodProcessing(targetDate, targetMeal, savedSources);
                        } else {
                            if (resultCode == RESULT_OK) {
                                showGlassToast("照片保存失败，请重新拍摄", Toast.LENGTH_SHORT);
                            }
                            finishMealPhotoPickMode(false);
                        }
                    }
                });
            }
        }, "meal-camera-result").start();
    }

    private void importSelectedMealMediaAsync(final List<Uri> uris, final boolean stickers) {
        final String targetDate = pendingPhotoDate;
        final String targetMeal = pendingPhotoMeal;
        final List<String> savedSources = new ArrayList<String>();
        if (targetDate == null || targetMeal == null || uris == null || uris.isEmpty()) {
            showGlassToast(stickers ? "贴纸读取失败" : "图片读取失败", Toast.LENGTH_SHORT);
            finishMealPhotoPickMode(false);
            return;
        }
        mealPhotoPickAwaitingResult = true;
        releaseThumbnailMemory();
        new Thread(new Runnable() {
            @Override
            public void run() {
                int saved = 0;
                for (Uri uri : uris) {
                    // Preserve at least the cutout engine's 1024px input where possible.
                    // The old 1440 limit halved a 1706px source before a second JPEG encode.
                    Bitmap bitmap = decodeBitmap(uri, stickers ? 1024 : 2048);
                    if(bitmap==null&&!stickers)bitmap=decodeBitmap(uri,1024);
                    if (bitmap == null) {
                        cleanupInternalCaptureUri(uri);
                        continue;
                    }
                    try {
                        boolean success = stickers
                                ? saveImportedMealSticker(targetDate, targetMeal, bitmap, false)
                                : saveMealBitmap(targetDate, targetMeal, bitmap, false, false, savedSources);
                        if (success) {
                            saved++;
                        }
                    } catch (OutOfMemoryError error) {
                        Log.e(LOG_TAG, "Out of memory while importing meal media", error);
                        releaseThumbnailMemory();
                    } finally {
                        recycleBitmapUnless(bitmap, null);
                        cleanupInternalCaptureUri(uri);
                    }
                }
                final int savedCount = saved;
                runOnUiThread(new Runnable() {
                    @Override
                    public void run() {
                        if (savedCount > 0) {
                            String message = savedCount == 1
                                    ? (stickers ? "贴纸已添加" : "照片已准备，请预览后确认")
                                    : (stickers ? "已添加" : "待确认") + savedCount + (stickers ? "张贴纸" : "张图片");
                            showGlassToast(message, Toast.LENGTH_SHORT);
                            finishMealPhotoPickMode(true);
                            if (!savedSources.isEmpty()) showFoodProcessing(targetDate, targetMeal, savedSources);
                        } else {
                            showGlassToast(stickers ? "贴纸读取失败" : "图片读取失败", Toast.LENGTH_SHORT);
                            finishMealPhotoPickMode(false);
                        }
                    }
                });
            }
        }, stickers ? "meal-sticker-import" : "meal-photo-import").start();
    }

    private void cleanupInternalCaptureUri(Uri uri) {
        if(uri==null||!"content".equals(uri.getScheme())||!MealCameraProvider.AUTHORITY.equals(uri.getAuthority()))return;
        try{getContentResolver().delete(uri,null,null);}catch(Exception ignored){}
    }

    private void finishMealPhotoPickMode(boolean renderAfter) {
        mealPhotoPickAwaitingResult = false;
        mealPhotoPickMode = false;
        pendingPhotoDate = null;
        pendingPhotoMeal = null;
        pendingMealCameraUri = null;
        clearPersistedPendingCameraState();
        updatePhotoFabState(false);
        updateFab();
        if (renderAfter) {
            renderCurrent();
        }
    }

    private List<Uri> selectedImageUris(Intent data) {
        List<Uri> uris = new ArrayList<Uri>();
        if (data == null) {
            return uris;
        }
        ClipData clip = data.getClipData();
        if (clip != null) {
            int limit = Math.min(clip.getItemCount(), 3);
            for (int i = 0; i < limit; i++) {
                Uri uri = clip.getItemAt(i).getUri();
                if (uri != null) {
                    uris.add(uri);
                }
            }
            if (clip.getItemCount() > 3) {
                showGlassToast("一次最多保存3张，已自动取前3张", Toast.LENGTH_SHORT);
            }
            return uris;
        }
        if (data.getData() != null) {
            uris.add(data.getData());
        }
        return uris;
    }

    private Bitmap loadAvatar() {
        File avatar = new File(getFilesDir(), "avatar.bin");
        if (!avatar.exists()) {
            return null;
        }
        BitmapFactory.Options bounds = new BitmapFactory.Options();
        bounds.inJustDecodeBounds = true;
        BitmapFactory.decodeFile(avatar.getAbsolutePath(), bounds);
        int target = dp(160);
        int sample = 1;
        while (bounds.outWidth / sample > target || bounds.outHeight / sample > target) {
            sample *= 2;
        }
        BitmapFactory.Options opts = new BitmapFactory.Options();
        opts.inSampleSize = Math.max(1, sample);
        return BitmapFactory.decodeFile(avatar.getAbsolutePath(), opts);
    }

    private Bitmap decodeBitmap(Uri uri, int target) {
        InputStream first = null;
        InputStream second = null;
        try {
            BitmapFactory.Options bounds = new BitmapFactory.Options();
            bounds.inJustDecodeBounds = true;
            first = getContentResolver().openInputStream(uri);
            if (first == null) {
                return null;
            }
            BitmapFactory.decodeStream(first, null, bounds);
            first.close();
            first = null;
            int safeTarget = Math.max(128, target);
            int sample = 1;
            while (bounds.outWidth / sample > safeTarget || bounds.outHeight / sample > safeTarget) {
                sample *= 2;
            }
            BitmapFactory.Options opts = new BitmapFactory.Options();
            opts.inSampleSize = Math.max(1, sample);
            opts.inPreferredConfig = Bitmap.Config.ARGB_8888;
            second = getContentResolver().openInputStream(uri);
            if (second == null) {
                return null;
            }
            Bitmap bitmap = BitmapFactory.decodeStream(second, null, opts);
            second.close();
            second = null;
            if (bitmap != null && Build.VERSION.SDK_INT >= 24) {
                try (InputStream exifStream = getContentResolver().openInputStream(uri)) {
                    android.media.ExifInterface exif = new android.media.ExifInterface(exifStream);
                    int orientation = exif.getAttributeInt(android.media.ExifInterface.TAG_ORIENTATION, 1);
                    Matrix transform = new Matrix();
                    if (orientation == 2) transform.setScale(-1, 1);
                    else if (orientation == 3) transform.setRotate(180);
                    else if (orientation == 4) transform.setScale(1, -1);
                    else if (orientation == 5) { transform.setRotate(90); transform.postScale(-1, 1); }
                    else if (orientation == 6) transform.setRotate(90);
                    else if (orientation == 7) { transform.setRotate(270); transform.postScale(-1, 1); }
                    else if (orientation == 8) transform.setRotate(270);
                    if (!transform.isIdentity()) {
                        Bitmap oriented = Bitmap.createBitmap(bitmap, 0, 0, bitmap.getWidth(), bitmap.getHeight(), transform, true);
                        if (oriented != bitmap) bitmap.recycle(); bitmap = oriented;
                    }
                } catch (Exception ignored) { }
            }
            return bitmap;
        } catch (OutOfMemoryError error) {
            releaseThumbnailMemory();
            Log.e(LOG_TAG, "Out of memory decoding " + uri, error);
            return null;
        } catch (Exception e) {
            Log.w(LOG_TAG, "Unable to decode " + uri, e);
            return null;
        } finally {
            closeQuietly(first);
            closeQuietly(second);
        }
    }

    private Bitmap centerCrop(Bitmap src, int width, int height) {
        int side = Math.min(src.getWidth(), src.getHeight());
        int x = Math.max(0, (src.getWidth() - side) / 2);
        int y = Math.max(0, (src.getHeight() - side) / 2);
        Bitmap square = Bitmap.createBitmap(src, x, y, side, side);
        Bitmap result = Bitmap.createScaledBitmap(square, width, height, true);
        recycleBitmapUnless(square, result);
        return result;
    }

    private void closeQuietly(InputStream stream) {
        if (stream == null) {
            return;
        }
        try {
            stream.close();
        } catch (Exception ignored) {
        }
    }

    private void recycleBitmapUnless(Bitmap bitmap, Bitmap keep) {
        if (bitmap != null && bitmap != keep && !bitmap.isRecycled()) {
            bitmap.recycle();
        }
    }

    private void releaseThumbnailMemory() {
        if(android.os.Looper.myLooper()!=android.os.Looper.getMainLooper()){
            runOnUiThread(()->releaseThumbnailMemory());return;
        }
        invalidateRootPages();
        mediaThumbnailEpoch++;mediaThumbnailInFlight.clear();
        mediaThumbnailCache.evictAll();
    }

    private void saveBitmap(Bitmap bitmap, File out, int quality) throws Exception {
        FileOutputStream fos = new FileOutputStream(out);
        try {
            if (!bitmap.compress(Bitmap.CompressFormat.JPEG, quality, fos)) {
                throw new Exception("JPEG encode failed");
            }
            fos.flush();
        } finally {
            fos.close();
        }
    }

    private List<MealOption> activeMeals() {
        JSONArray arr = profile.optJSONArray("meals");
        if (arr == null || arr.length() == 0) {
            arr = new JSONArray();
            // Reading legacy defaults must not write settings during a UI-mode switch.
            for (String key : DEFAULT_MEAL_KEYS) arr.put(key);
        }
        List<MealOption> result = new ArrayList<MealOption>();
        for (int i = 0; i < arr.length(); i++) {
            MealOption meal = mealByKey(arr.optString(i));
            if (meal != null) {
                result.add(meal);
            }
        }
        sortMeals(result);
        if (result.isEmpty()) {
            result.add(new MealOption("breakfast", "早餐", 0));
        }
        return result;
    }

    private List<MealOption> visibleMealsForDate(String date) {
        JSONObject day = days.optJSONObject(date);
        return visibleMealsForDay(day == null ? new JSONObject() : day);
    }

    private List<MealOption> visibleMealsForDay(JSONObject day) {
        List<MealOption> result = new ArrayList<MealOption>(activeMeals());
        JSONArray extras = day.optJSONArray("extraMeals");
        if (extras != null) {
            for (int i = 0; i < extras.length(); i++) {
                addMealIfMissing(result, extras.optString(i));
            }
        }
        for (MealOption meal : allMealOptions()) {
            if (mealHasAnyData(day, meal.key)) {
                addMealIfMissing(result, meal.key);
            }
        }
        sortMeals(result);
        return result;
    }

    private void sortMeals(List<MealOption> meals) {
        Collections.sort(meals, new Comparator<MealOption>() {
            @Override
            public int compare(MealOption a, MealOption b) {
                return mealOrderIndex(a.key) - mealOrderIndex(b.key);
            }
        });
    }

    private int mealOrderIndex(String key) {
        for (int i = 0; i < AVAILABLE_MEAL_KEYS.length; i++) {
            if (AVAILABLE_MEAL_KEYS[i].equals(key)) {
                return i;
            }
        }
        return 999;
    }

    private void addMealIfMissing(List<MealOption> meals, String key) {
        if (mealListContains(meals, key)) {
            return;
        }
        MealOption meal = mealByKey(key);
        if (meal != null) {
            meals.add(meal);
        }
    }

    private boolean mealHasAnyData(JSONObject day, String key) {
        JSONObject meal = day == null ? null : day.optJSONObject(key);
        if (meal == null) {
            return false;
        }
        JSONArray photos = meal.optJSONArray("photos");
        JSONArray stickers = meal.optJSONArray("stickers");
        return meal.optString("text", "").trim().length() > 0
                || meal.optString("emoji", "").trim().length() > 0
                || meal.optString("snackMood", "").trim().length() > 0
                || meal.optInt("manualCalories", 0) > 0
                || meal.optInt("mealCostCents", 0) > 0
                || meal.optBoolean("skipped", false)
                || (photos != null && photos.length() > 0)
                || (stickers != null && stickers.length() > 0);
    }

    private List<MealOption> allMealOptions() {
        List<MealOption> result = new ArrayList<MealOption>();
        for (int i = 0; i < AVAILABLE_MEAL_KEYS.length; i++) {
            result.add(new MealOption(AVAILABLE_MEAL_KEYS[i], AVAILABLE_MEAL_TITLES[i], i));
        }
        return result;
    }

    private MealOption mealByKey(String key) {
        for (int i = 0; i < AVAILABLE_MEAL_KEYS.length; i++) {
            if (AVAILABLE_MEAL_KEYS[i].equals(key)) {
                return new MealOption(AVAILABLE_MEAL_KEYS[i], AVAILABLE_MEAL_TITLES[i], i);
            }
        }
        return null;
    }







    private String mealTitle(String key) {
        MealOption meal = mealByKey(key);
        return meal == null ? key : meal.title;
    }


    private List<String> mealHintList(String key) {
        List<String> hints = new ArrayList<String>();
        JSONObject custom = profile.optJSONObject("mealHints");
        JSONArray arr = custom == null ? null : custom.optJSONArray(key);
        if (arr != null) {
            for (int i = 0; i < arr.length(); i++) {
                String value = arr.optString(i).trim();
                if (value.length() > 0) {
                    hints.add(value);
                }
            }
        }
        if (hints.isEmpty()) {
            int idx = ManualMealPrompts.mealHintIndex(key);
            for (String value : MEAL_HINTS[idx]) {
                hints.add(value);
            }
        }
        return hints;
    }


    private List<String> homeHintList() {
        List<String> hints = new ArrayList<String>();
        JSONArray custom = profile.optJSONArray("homeHints");
        if (custom != null) {
            for (int i = 0; i < custom.length(); i++) {
                String value = sanitizeHomeHintText(stripHintTail(custom.optString(i))).trim();
                if (value.length() > 0) {
                    hints.add(value);
                }
            }
        }
        if (hints.isEmpty()) {
            for (String value : HOME_HINTS) {
                hints.add(value);
            }
        }
        return hints;
    }



    private List<String> hintValues(String kind, String key) {
        if ("home".equals(kind)) {
            return homeHintList();
        }
        if ("skip".equals(kind)) {
            return skipReminderList(key);
        }
        return mealHintList(key);
    }



    private String stripHintTail(String value) {
        if (value == null) {
            return "";
        }
        return value.replace(HINT_TAIL, "").trim();
    }

    private String sanitizeHomeHintText(String value) {
        if (value == null) {
            return "";
        }
        return value
                .replace("，长按文字可以插入emoji", "")
                .replace("，长按文字可以插入 emoji", "")
                .replace("，长按文字还能塞进emoji", "")
                .replace("，长按文字还能塞进 emoji", "")
                .replace("长按文字可以插入emoji，", "")
                .replace("长按文字可以插入 emoji，", "")
                .replace("长按文字还能塞进emoji，", "")
                .replace("长按文字还能塞进 emoji，", "")
                .replace("长按文字加emoji，", "")
                .replace("长按文字加 emoji，", "")
                .replace("文字、图片和小表情", "文字和图片")
                .replace("照片、文字、emoji", "照片和文字")
                .replace("文字、图片、emoji", "文字和图片")
                .replace("，，", "，")
                .replace("，。", "。")
                .trim();
    }

    private void saveHomeHints(List<EditText> inputs) {
        JSONArray arr = new JSONArray();
        for (EditText input : inputs) {
            String value = sanitizeHomeHintText(stripHintTail(input.getText().toString()));
            if (value.length() > 0) {
                arr.put(value);
            }
        }
        try {
            if (arr.length() == 0) {
                profile.remove("homeHints");
            } else {
                profile.put("homeHints", arr);
            }
            hintSeed = (int) (System.currentTimeMillis() % 100000);
            saveProfile();
        } catch (JSONException ignored) {
        }
    }

    private void saveHintSection(String kind, String key, List<EditText> inputs) {
        if ("home".equals(kind)) {
            saveHomeHints(inputs);
            return;
        }
        if ("skip".equals(kind)) {
            saveGroupedHints("skipHints", key, inputs);
            return;
        }
        saveGroupedHints("mealHints", key, inputs);
    }

    private void saveGroupedHints(String objectName, String key, List<EditText> inputs) {
        JSONObject obj = profile.optJSONObject(objectName);
        if (obj == null) {
            obj = new JSONObject();
        }
        JSONArray arr = new JSONArray();
        for (EditText input : inputs) {
            String value = input.getText().toString().trim();
            if (value.length() > 0) {
                arr.put(value);
            }
        }
        try {
            if (arr.length() == 0) {
                obj.remove(key);
            } else {
                obj.put(key, arr);
            }
            if (obj.length() == 0) {
                profile.remove(objectName);
            } else {
                profile.put(objectName, obj);
            }
            hintSeed = (int) (System.currentTimeMillis() % 100000);
            saveProfile();
        } catch (JSONException ignored) {
        }
    }


    private List<String> skipReminderList(String key) {
        List<String> hints = new ArrayList<String>();
        JSONObject custom = profile.optJSONObject("skipHints");
        JSONArray arr = custom == null ? null : custom.optJSONArray(key);
        if (arr != null) {
            for (int i = 0; i < arr.length(); i++) {
                String value = arr.optString(i).trim();
                if (value.length() > 0) {
                    hints.add(value);
                }
            }
        }
        if (hints.isEmpty()) {
            String[] defaults = skipDefaultPool(key);
            for (String value : defaults) {
                hints.add(value);
            }
        }
        return hints;
    }

    private String[] skipDefaultPool(String key) {
        if ("many".equals(key)) {
            return SKIP_REMINDERS_MANY;
        }
        if ("three".equals(key)) {
            return SKIP_REMINDERS_THREE;
        }
        if ("two".equals(key)) {
            return SKIP_REMINDERS_TWO;
        }
        return SKIP_REMINDERS;
    }

