    private String layoutTitle(int level) {
        if (level <= 12) {
            return "紧凑";
        }
        if (level <= 34) {
            return "偏紧凑";
        }
        if (level <= 66) {
            return "适中";
        }
        if (level <= 88) {
            return "舒展";
        }
        return "很舒展";
    }

    private String layoutValueForLevel(int level) {
        if (level <= 34) {
            return "compact";
        }
        if (level >= 67) {
            return "cozy";
        }
        return "medium";
    }

