    private Drawable stickerFrameBackground(boolean notebookPaper) {
        String style = stickerFrameStyle();
        if ("none".equals(style)) {
            return round(Color.TRANSPARENT, dp(14), Color.TRANSPARENT, 0);
        }
        int paperTop = notebookPaper ? notebookPaperBackgroundTop() : Color.WHITE;
        int paperBottom = notebookPaper ? notebookPaperBackgroundBottom() : accentSoft;
        int paperFill = notebookPaper
                ? blendColor(paperTop, Color.WHITE, nightDecoration() ? 0.04f : 0.18f)
                : Color.argb(130, 255, 255, 255);
        int themeFill = nightDecoration() ? Color.rgb(42, 44, 49) : blendColor(accentSoft, Color.WHITE, 0.28f);
        int paperStroke = notebookPaper
                ? blendColor(paperBottom, accent, nightDecoration() ? 0.10f : 0.16f)
                : accentSoft;
        GradientDrawable drawable = new GradientDrawable();
        drawable.setShape(GradientDrawable.RECTANGLE);
        drawable.setCornerRadius("plate".equals(style) ? dp(999) : dp(16));
        if ("stamp".equals(style)) {
            drawable.setColor(nightDecoration() ? Color.rgb(36, 38, 42)
                    : (notebookPaper ? paperFill : themeFill));
            drawable.setStroke(dp(2), notebookPaper ? paperStroke : blendColor(accent, accentSoft, 0.24f),
                    dp(3), dp(3));
        } else if ("bubble".equals(style)) {
            drawable.setColor(nightDecoration() ? Color.argb(80, 88, 96, 108)
                    : (notebookPaper ? adjustAlpha(paperFill, 176) : blendColor(accentSoft, Color.WHITE, 0.16f)));
            drawable.setStroke(dp(2), notebookPaper ? adjustAlpha(paperStroke, 210) : Color.argb(205, 255, 255, 255));
        } else if ("plate".equals(style)) {
            drawable.setColor(nightDecoration() ? Color.rgb(41, 42, 46)
                    : (notebookPaper ? blendColor(paperTop, Color.WHITE, 0.24f) : blendColor(accentSoft, Color.WHITE, 0.18f)));
            drawable.setStroke(dp(2), notebookPaper ? paperStroke : accent);
        } else if ("dashed".equals(style)) {
            drawable.setColor(nightDecoration() ? Color.rgb(38, 40, 45)
                    : (notebookPaper ? adjustAlpha(paperFill, 148) : Color.argb(118, 255, 255, 255)));
            drawable.setStroke(dp(1), notebookPaper ? paperStroke : accent, dp(5), dp(4));
        } else {
            drawable.setColor(nightDecoration() ? Color.rgb(42, 44, 49) : paperFill);
            drawable.setStroke(dp(1), paperStroke);
        }
        return drawable;
    }

