    private void backupData() {
        showGlassToast("正在备份数据...", Toast.LENGTH_SHORT);
        new Thread(new Runnable() {
            @Override
            public void run() {
                Uri uri = null;
                try {
                    String fileName = "eat_record_backup_" + new SimpleDateFormat("yyyyMMdd_HHmmss", Locale.CHINA)
                            .format(new Date()) + ".eatrecordbackup";
                    uri = createBackupUri(fileName);
                    if (uri == null) {
                        throw new Exception("backup uri missing");
                    }
                    OutputStream out = getContentResolver().openOutputStream(uri);
                    if (out == null) {
                        throw new Exception("backup output missing");
                    }
                    try {
                        writeBackup(out, false);
                    } finally {
                        out.close();
                    }
                    finishBackupUri(uri);
                    final String done = fileName;
                    runOnUiThread(new Runnable() {
                        @Override
                        public void run() {
                            showGlassToast("已备份到 Downloads/一蔬一饭 backup/" + done, Toast.LENGTH_LONG);
                        }
                    });
                } catch (final Exception | OutOfMemoryError e) {
                    if (uri != null) {
                        try {
                            if("file".equals(uri.getScheme()))new File(uri.getPath()).delete();
                            else getContentResolver().delete(uri, null, null);
                        } catch (Exception ignored) {
                        }
                    }
                    runOnUiThread(new Runnable() {
                        @Override
                        public void run() {
                            showGlassToast("备份失败，请稍后再试", Toast.LENGTH_SHORT);
                        }
                    });
                }
            }
        }).start();
    }

    private Uri createBackupUri(String fileName) throws Exception {
        if (Build.VERSION.SDK_INT >= 29) {
            ContentValues values = new ContentValues();
            values.put(MediaStore.MediaColumns.DISPLAY_NAME, fileName);
            values.put(MediaStore.MediaColumns.MIME_TYPE, "application/octet-stream");
            values.put(MediaStore.MediaColumns.RELATIVE_PATH, Environment.DIRECTORY_DOWNLOADS + "/一蔬一饭 backup");
            values.put(MediaStore.MediaColumns.IS_PENDING, 1);
            return getContentResolver().insert(MediaStore.Downloads.EXTERNAL_CONTENT_URI, values);
        }
        File dir = new File(Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_DOWNLOADS), "一蔬一饭 backup");
        if (!dir.exists() && !dir.mkdirs()) {
            throw new Exception("backup dir missing");
        }
        return Uri.fromFile(new File(dir, fileName));
    }

    private void finishBackupUri(Uri uri) {
        if (uri == null || Build.VERSION.SDK_INT < 29) {
            return;
        }
        ContentValues done = new ContentValues();
        done.put(MediaStore.MediaColumns.IS_PENDING, 0);
        getContentResolver().update(uri, done, null, null);
    }

