    private String updateNotes(JSONObject update) {
        JSONArray arr = update.optJSONArray("notes");
        if (arr != null && arr.length() > 0) {
            String parsed = latestNotesFromLines(arr, update.optString("versionName", "").trim());
            if (parsed.length() > 0) {
                return parsed;
            }
        }
        String text = update.optString("notes", "").trim();
        if (text.length() > 0) {
            String parsed = latestNotesFromText(text, update.optString("versionName", "").trim());
            if (parsed.length() > 0) {
                return parsed;
            }
            return text;
        }
        return "新版本已经准备好啦。";
    }

    private String latestNotesFromText(String text, String targetVersion) {
        JSONArray arr = new JSONArray();
        String[] lines = text.split("\\r?\\n");
        for (int i = 0; i < lines.length; i++) {
            String item = lines[i].trim();
            if (item.length() > 0) {
                arr.put(item);
            }
        }
        return latestNotesFromLines(arr, targetVersion);
    }

    private String latestNotesFromLines(JSONArray arr, String targetVersion) {
        String bestVersion = "";
        StringBuilder best = new StringBuilder();
        String currentVersion = "";
        StringBuilder current = new StringBuilder();
        boolean hasVersionGroups = false;
        StringBuilder ungrouped = new StringBuilder();
        for (int i = 0; i < arr.length(); i++) {
            String item = arr.optString(i).trim();
            if (item.length() == 0) {
                continue;
            }
            if (isVersionName(item)) {
                hasVersionGroups = true;
                if (currentVersion.length() > 0 && isBetterUpdateNoteGroup(currentVersion, bestVersion, targetVersion)) {
                    bestVersion = currentVersion;
                    best = current;
                }
                currentVersion = item;
                current = new StringBuilder(item);
                continue;
            }
            String line = item.startsWith("•") ? item : "• " + item;
            if (hasVersionGroups || currentVersion.length() > 0) {
                if (current.length() > 0) {
                    current.append("\n");
                }
                current.append(line);
            } else {
                if (ungrouped.length() > 0) {
                    ungrouped.append("\n");
                }
                ungrouped.append(line);
            }
        }
        if (currentVersion.length() > 0 && isBetterUpdateNoteGroup(currentVersion, bestVersion, targetVersion)) {
            bestVersion = currentVersion;
            best = current;
        }
        if (best.length() > 0) {
            return best.toString();
        }
        if (ungrouped.length() > 0) {
            return ungrouped.toString();
        }
        StringBuilder fallback = new StringBuilder();
        for (int i = 0; i < arr.length(); i++) {
            String item = arr.optString(i).trim();
            if (item.length() > 0) {
                if (fallback.length() > 0) {
                    fallback.append("\n");
                }
                fallback.append(item.startsWith("•") || isVersionName(item) ? item : "• " + item);
            }
        }
        return fallback.toString();
    }

    private boolean isBetterUpdateNoteGroup(String version, String currentBest, String targetVersion) {
        if (targetVersion != null && targetVersion.length() > 0) {
            if (version.equals(targetVersion)) {
                return true;
            }
            if (currentBest.equals(targetVersion)) {
                return false;
            }
        }
        return currentBest.length() == 0 || compareVersionNames(version, currentBest) > 0;
    }

