    private void openOpenListDownload(final String apkPath, final String fallbackUrl) {
        showGlassToast("正在准备下载链接...", Toast.LENGTH_SHORT);
        new Thread(new Runnable() {
            @Override
            public void run() {
                String url = "";
                try {
                    String requested=apkPath;
                    if(requested==null||requested.isEmpty())requested=fallbackUrl==null?"":Uri.parse(fallbackUrl).getPath();
                    url = fetchOpenListRawUrl(requested);
                } catch (Exception ignored) {
                }
                final String target = url.length() > 0 ? url : fallbackUrl;
                runOnUiThread(new Runnable() {
                    @Override
                    public void run() {
                        if (target != null && target.length() > 0) {
                            openUpdateUrl(target);
                        } else {
                            showGlassToast("下载链接暂时不可用", Toast.LENGTH_SHORT);
                        }
                    }
                });
            }
        }).start();
    }

