    private void shakeMarkedEmoji(final View view) {
        view.animate().rotation(-5f).setDuration(55).withEndAction(new Runnable() {
            @Override
            public void run() {
                view.animate().rotation(5f).setDuration(70).withEndAction(new Runnable() {
                    @Override
                    public void run() {
                        view.animate().rotation(0f).setDuration(80).start();
                    }
                }).start();
            }
        }).start();
    }

    private void shakeMediaItem(final View view, final int count) {
        shakeMediaItem(view, count, 0f);
    }

    private void shakeMediaItem(final View view, final int count, final float baseRotation) {
        if (view == null || count >= 5) {
            if (view != null) {
                view.animate().rotation(baseRotation).setDuration(90).start();
            }
            return;
        }
        float next = baseRotation + (count % 2 == 0 ? -2.4f : 2.4f);
        view.animate().rotation(next).setDuration(68).withEndAction(new Runnable() {
            @Override
            public void run() {
                shakeMediaItem(view, count + 1, baseRotation);
            }
        }).start();
    }

    private void exitMediaEditMode(boolean animate) {
        if (editingMediaItems.isEmpty()) {
            return;
        }
        List<View> snapshot = new ArrayList<View>(editingMediaItems);
        editingMediaItems.clear();
        for (View item : snapshot) {
            if (item == null) {
                continue;
            }
            if(item.getTag() instanceof MealTextAction){((MealTextAction)item.getTag()).exitEdit();continue;}
            if (item.getTag() instanceof PhotoAction) {
                PhotoAction action = (PhotoAction) item.getTag();
                action.exitEdit();
                if (animate) {
                    item.animate().rotation(action.baseRotation)
                            .translationX(action.baseTranslationX).translationY(action.baseTranslationY)
                            .scaleX(1f).scaleY(1f).setDuration(150).start();
                    item.setElevation(action.baseElevation);
                } else {
                    item.setRotation(action.baseRotation);
                    item.setTranslationX(action.baseTranslationX);
                    item.setTranslationY(action.baseTranslationY);
                    item.setElevation(action.baseElevation);
                    item.setScaleX(1f);
                    item.setScaleY(1f);
                }
                continue;
            }
            item.animate().cancel();
            if (animate) {
                item.animate().rotation(0f).translationX(0f).translationY(0f)
                        .scaleX(1f).scaleY(1f).setDuration(150).start();
            } else {
                item.setRotation(0f);
                item.setTranslationX(0f);
                item.setTranslationY(0f);
                item.setScaleX(1f);
                item.setScaleY(1f);
            }
        }
    }

