    private void launchInternalFoodCapture(String date,String meal,boolean gallery) {
        pendingPhotoDate=date;pendingPhotoMeal=meal;pendingMealCameraUri=null;persistPendingMealCameraState();
        Intent intent=new Intent(this,FoodCaptureActivity.class).putExtra(FoodCaptureActivity.EXTRA_DATE,date)
                .putExtra(FoodCaptureActivity.EXTRA_MEAL,meal).putExtra(FoodCaptureActivity.EXTRA_GALLERY,gallery);
        try{mealPhotoPickAwaitingResult=true;startActivityForResult(intent,REQ_INTERNAL_FOOD_CAPTURE);}
        catch(Exception error){mealPhotoPickAwaitingResult=false;clearPersistedPendingCameraState();showGlassToast("相机页面暂时无法打开",Toast.LENGTH_SHORT);}
    }

    /** Kept for an in-flight result from an older installation; normal UI uses the in-app camera. */


    private void clearPendingMealCameraOutput() {
        Uri uri = pendingMealCameraUri;
        pendingMealCameraUri = null;
        clearPersistedPendingCameraState();
        if (uri == null) {
            return;
        }
        try {
            getContentResolver().delete(uri, null, null);
        } catch (Exception e) {
            Log.w(LOG_TAG, "Unable to remove camera output " + uri, e);
        } finally {
            try {
                revokeUriPermission(uri,
                        Intent.FLAG_GRANT_READ_URI_PERMISSION | Intent.FLAG_GRANT_WRITE_URI_PERMISSION);
            } catch (Exception ignored) {
            }
        }
    }

    private void persistPendingMealCameraState() {
        if (prefs == null) {
            return;
        }
        prefs.edit()
                .putString(PENDING_CAMERA_URI_KEY,
                        pendingMealCameraUri == null ? "" : pendingMealCameraUri.toString())
                .putString(PENDING_CAMERA_DATE_KEY, pendingPhotoDate == null ? "" : pendingPhotoDate)
                .putString(PENDING_CAMERA_MEAL_KEY, pendingPhotoMeal == null ? "" : pendingPhotoMeal)
                .putLong(PENDING_CAMERA_TIME_KEY, System.currentTimeMillis())
                .commit();
    }

    private void restorePendingMealCameraState() {
        if (prefs == null) {
            return;
        }
        long savedAt = prefs.getLong(PENDING_CAMERA_TIME_KEY, 0L);
        String date = prefs.getString(PENDING_CAMERA_DATE_KEY, "");
        String meal = prefs.getString(PENDING_CAMERA_MEAL_KEY, "");
        if (savedAt <= 0L || System.currentTimeMillis() - savedAt > 60L * 60L * 1000L
                || date == null || date.length() == 0 || meal == null || meal.length() == 0) {
            clearPersistedPendingCameraState();
            return;
        }
        pendingPhotoDate = date;
        pendingPhotoMeal = meal;
        String uri = prefs.getString(PENDING_CAMERA_URI_KEY, "");
        pendingMealCameraUri = uri == null || uri.length() == 0 ? null : Uri.parse(uri);
        homeDateKey = date;
    }

    private void clearPersistedPendingCameraState() {
        if (prefs == null) {
            return;
        }
        prefs.edit()
                .remove(PENDING_CAMERA_URI_KEY)
                .remove(PENDING_CAMERA_DATE_KEY)
                .remove(PENDING_CAMERA_MEAL_KEY)
                .remove(PENDING_CAMERA_TIME_KEY)
                .apply();
    }

