    private View mediaThumbView(final String date, final String mealKey, final String fileName,
                                final String arrayKey, final String title, boolean sticker, int size) {
        final FrameLayout frame = mediaImageFrame(fileName, sticker, size);
        PhotoAction action = bindMediaControls(frame, date, mealKey, fileName, arrayKey, title, 20,
                () -> showPhotoViewer(date, mealKey, fileName));
        action.mediaContent = frame.getChildAt(0);
        JSONObject linked = NutritionStore.findByMedia(NutritionStore.meal(days, date, mealKey), fileName);
        if (linked != null) {
            action.foodId = linked.optString("id");
            action.mediaContent.setRotation(NutritionStore.displayRotation(linked));
        }
        return frame;
    }

    /** Both journal imports and legacy stickers use the same selection/edit controller. */
    private PhotoAction bindMediaControls(final FrameLayout frame, final String date, final String mealKey,
                                          final String fileName, final String arrayKey, final String title,
                                          int controlSize, final Runnable open) {
        frame.setClickable(true);

        final TextView rotate = mediaEditControl("↺");
        rotate.setContentDescription("向左旋转90度");
        FrameLayout.LayoutParams rotateLp = new FrameLayout.LayoutParams(dp(controlSize), dp(controlSize));
        rotateLp.gravity = Gravity.LEFT | Gravity.TOP;
        rotateLp.topMargin = -dp(1);
        rotateLp.leftMargin = -dp(1);
        frame.addView(rotate, rotateLp);

        final TextView close = mediaEditControl("×");
        close.setContentDescription("删除这张" + title);
        FrameLayout.LayoutParams closeLp = new FrameLayout.LayoutParams(dp(controlSize), dp(controlSize));
        closeLp.gravity = Gravity.RIGHT | Gravity.TOP;
        closeLp.topMargin = -dp(1);
        closeLp.rightMargin = -dp(1);
        frame.addView(close, closeLp);
        if (controlSize >= 48) {
            rotate.setBackground(new android.graphics.drawable.InsetDrawable(rotate.getBackground(), dp(8)));
            close.setBackground(new android.graphics.drawable.InsetDrawable(close.getBackground(), dp(8)));
        }

        final PhotoAction action = new PhotoAction(date, mealKey, fileName, arrayKey, title, close, rotate);
        action.itemView = frame;
        frame.setTag(action);
        frame.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                if (action.editing) {
                    return;
                }
                open.run();
            }
        });
        close.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                confirmDeleteMedia(action);
            }
        });
        rotate.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                rotateMealMediaLeft(action);
            }
        });
        return action;
    }

    private View journalText(final String date,final DayFoodEntries.Entry entry,View text){
        final FrameLayout frame=new FrameLayout(this);
        text.setBackground(null);text.setOnClickListener(null);text.setClickable(false);text.setLongClickable(false);
        text.setFocusable(false);text.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO_HIDE_DESCENDANTS);
        frame.addView(text,new FrameLayout.LayoutParams(-1,-2));
        TextView close=mediaEditControl("×");close.setTag("meal_text_delete");
        close.setContentDescription("删除"+entry.mealTitle+"文字");
        close.setBackground(new android.graphics.drawable.InsetDrawable(close.getBackground(),dp(8)));
        FrameLayout.LayoutParams closeLp=new FrameLayout.LayoutParams(dp(48),dp(48),Gravity.TOP|Gravity.RIGHT);
        frame.addView(close,closeLp);
        final MealTextAction action=new MealTextAction(frame,close,date,entry.mealKey,entry.textValue);
        frame.setTag(action);
        frame.setFocusable(true);frame.setClickable(true);frame.setLongClickable(true);
        frame.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_YES);
        frame.setContentDescription(entry.mealTitle+"，"+entry.title+"，点按编辑，长按显示删除文字");
        frame.setOnClickListener(v->{if(!action.editing){retainHomeFoodDate(date);showMealRecordEditor(date,entry.mealKey);}});
        frame.setOnLongClickListener(v->{retainHomeFoodDate(date);exitMediaEditMode(false);editingMediaItems.add(frame);action.enterEdit();return true;});
        close.setOnClickListener(v->confirmDeleteMealText(action));
        return frame;
    }

    private void confirmDeleteMealText(final MealTextAction action){
        PaperComponents.dialogBuilder(this,nightDecoration()).setTitle("删除这段文字？")
            .setMessage("仅删除这餐填写的文字，餐图、营养和手动热量保留。")
            .setNegativeButton("取消",null).setPositiveButton("删除",(dialog,which)->{
                boolean removed=deleteMealText(action.date,action.meal,action.expected);
                exitMediaEditMode(false);days=readJson(DATA_KEY);renderCurrent();
                showGlassToast(removed?"文字已删除":"文字已更新，请核对后重试",Toast.LENGTH_SHORT);
            }).show();
    }

    private boolean deleteMealText(String date,String mealKey,String expected){
        synchronized(NutritionStore.LOCK){
            JSONObject latest=NutritionStore.read(prefs,DATA_KEY),day=latest.optJSONObject(date),meal=NutritionStore.meal(latest,date,mealKey);
            if(meal==null||expected==null||!expected.equals(meal.optString("text")))return false;
            try{
                JSONObject updated=ManualMealText.updatedInlineMeal(meal,"");
                if(updated==null)return false;day.put(mealKey,updated);
                if(!prefs.edit().putString(DATA_KEY,latest.toString()).commit())return false;
                days=latest;return true;
            }catch(JSONException failed){return false;}
        }
    }

    private final class MealTextAction {
        final FrameLayout frame;final View close;final String date,meal,expected;boolean editing;
        MealTextAction(FrameLayout frame,View close,String date,String meal,String expected){this.frame=frame;this.close=close;this.date=date;this.meal=meal;this.expected=expected;}
        void enterEdit(){
            editing=true;playMediaEditFeedback();
            frame.setBackground(round(adjustAlpha(accentSoft,nightDecoration()?105:90),dp(22),adjustAlpha(accent,65),dp(1)));
            close.setVisibility(View.VISIBLE);close.bringToFront();
        }
        void exitEdit(){editing=false;close.setVisibility(View.GONE);frame.setBackground(null);}
    }

    private View journalMedia(final String date, final DayFoodEntries.Entry entry, View image) {
        return journalMedia(date,entry,image,null);
    }

    private View journalMedia(final String date, final DayFoodEntries.Entry entry, View image, Runnable tap) {
        FrameLayout frame = new FrameLayout(this) {
            private boolean foodHit(MotionEvent event) {
                return !(image instanceof TodayPaperView.HitTestMedia)
                        || ((TodayPaperView.HitTestMedia)image).containsMediaPoint(
                            event.getX()-image.getLeft()-image.getTranslationX(),
                            event.getY()-image.getTop()-image.getTranslationY());
            }
            @Override public boolean dispatchTouchEvent(MotionEvent event) {
                boolean editing=getTag() instanceof PhotoAction&&((PhotoAction)getTag()).editing;
                if(entry.isFood()&&!editing){
                    if(event.getActionMasked()==MotionEvent.ACTION_DOWN&&!foodHit(event))return false;
                    if(event.getActionMasked()==MotionEvent.ACTION_UP&&!foodHit(event)){
                        MotionEvent cancel=MotionEvent.obtain(event);cancel.setAction(MotionEvent.ACTION_CANCEL);
                        boolean handled=super.dispatchTouchEvent(cancel);cancel.recycle();return handled;
                    }
                }
                return super.dispatchTouchEvent(event);
            }
        };
        frame.setClipChildren(false); frame.setClipToPadding(false);
        FrameLayout.LayoutParams imageLp = new FrameLayout.LayoutParams(-1, -1);
        imageLp.setMargins(dp(12), dp(12), dp(12), dp(12));
        frame.addView(image, imageLp);
        String arrayKey = entry.isFood() ? "photos" : entry.sticker ? "stickers" : "photos";
        String file = entry.isFood() ? entry.item.optString("sourcePhoto") : entry.fileName;
        PhotoAction action = bindMediaControls(frame, date, entry.mealKey, file, arrayKey,
                entry.sticker || entry.isFood() ? "贴纸" : "图片", 48, tap!=null?tap:() -> {
                    retainHomeFoodDate(date);
                    if (entry.isFood()) foodUi().details(date, entry.mealKey, entry.item);
                    else showPhotoViewer(date, entry.mealKey, entry.fileName);
                });
        action.foodId = entry.isFood() ? entry.item.optString("id") : "";
        action.mediaContent = image;
        installStandaloneMediaLongPress(frame);
        frame.setFocusable(true);frame.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_YES);
        frame.setContentDescription(entry.mealTitle + "，" + entry.title + (entry.isFood()?"，点按图片查看营养详情":"") + "，长按显示旋转和删除");
        return frame;
    }

    private void installStandaloneMediaLongPress(final View item) {
        if (item == null || !(item.getTag() instanceof PhotoAction)) {
            return;
        }
        item.setLongClickable(true);
        item.setOnLongClickListener(new View.OnLongClickListener() {
            @Override
            public boolean onLongClick(View v) {
                if (!(v.getTag() instanceof PhotoAction)) {
                    return false;
                }
                exitMediaEditMode(false);
                editingMediaItems.clear();
                PhotoAction action = (PhotoAction) v.getTag();
                if (action.usesExpandedChildren()) {
                    playMediaEditFeedback();
                    for (View child : action.stackChildViews) {
                        if (child != null && child.getTag() instanceof PhotoAction) {
                            editingMediaItems.add(child);
                            ((PhotoAction) child.getTag()).enterEdit(child, false);
                        }
                    }
                } else {
                    editingMediaItems.add(v);
                    action.enterEdit(v);
                }
                return true;
            }
        });
    }

    private FrameLayout mediaImageFrame(String fileName, boolean sticker, int size) {
        FrameLayout frame = new FrameLayout(this);
        frame.setClipChildren(false);
        frame.setClipToPadding(false);
        frame.setPadding(dp(1), dp(1), dp(1), dp(1));
        RoundedImageView image = new RoundedImageView(this);
        image.setRadius(sticker ? stickerImageRadius(size) : dp(spaceByLayout(12, 10, 8)));
        image.setScaleType(sticker ? ImageView.ScaleType.FIT_CENTER : ImageView.ScaleType.CENTER_CROP);
        if (sticker) {
            image.setBackground(stickerFrameBackground());
            int pad = stickerFramePadding();
            image.setPadding(pad, pad, pad, pad);
        }
        loadMediaThumbnail(image, fileName, size);
        frame.addView(image, new FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
        return frame;
    }

    private View mediaStackView(final String date, final String mealKey, final List<String> group,
                                final String arrayKey, final String title, final boolean sticker, final int size) {
        final FrameLayout stack = new FrameLayout(this);
        stack.setClipChildren(false);
        stack.setClipToPadding(false);
        stack.setClickable(true);
        final int count = group.size();
        final String topName = group.get(count - 1);
        final boolean[] expanded = new boolean[]{false};
        final List<View> popped = new ArrayList<View>();

        for (int i = count - 2; i >= 0; i--) {
            final String childName = group.get(i);
            View child = mediaThumbView(date, mealKey, childName, arrayKey, title, sticker, size);
            child.setVisibility(View.INVISIBLE);
            child.setAlpha(0f);
            child.setScaleX(0.86f);
            child.setScaleY(0.86f);
            child.setOnClickListener(new View.OnClickListener() {
                @Override
                public void onClick(View v) {
                    PhotoAction childAction = v.getTag() instanceof PhotoAction
                            ? (PhotoAction) v.getTag() : null;
                    if (childAction != null && childAction.editing) {
                        return;
                    }
                    showPhotoViewer(date, mealKey, childName);
                }
            });
            popped.add(child);
            stack.addView(child, new FrameLayout.LayoutParams(size, size));
        }

        View top = mediaThumbView(date, mealKey, topName, arrayKey, title, sticker, size);
        top.setOnClickListener(null);
        top.setClickable(false);
        stack.addView(top, new FrameLayout.LayoutParams(size, size));

        final TextView badge = label("×" + count, 13, Color.WHITE, true);
        badge.setGravity(Gravity.CENTER);
        badge.setBackground(round(Color.argb(232, Color.red(accent), Color.green(accent), Color.blue(accent)),
                dp(11), Color.WHITE, dp(1)));
        badge.setClickable(true);
        attachPressAnimation(badge);
        FrameLayout.LayoutParams badgeLp = new FrameLayout.LayoutParams(dp(32), dp(22));
        badgeLp.gravity = Gravity.RIGHT | Gravity.BOTTOM;
        badgeLp.rightMargin = -dp(1);
        badgeLp.bottomMargin = -dp(1);
        stack.addView(badge, badgeLp);

        final TextView rotate = mediaEditControl("↺");
        FrameLayout.LayoutParams rotateLp = new FrameLayout.LayoutParams(dp(20), dp(20));
        rotateLp.gravity = Gravity.LEFT | Gravity.TOP;
        rotateLp.topMargin = -dp(1);
        rotateLp.leftMargin = -dp(1);
        stack.addView(rotate, rotateLp);

        final TextView close = mediaEditControl("×");
        FrameLayout.LayoutParams closeLp = new FrameLayout.LayoutParams(dp(20), dp(20));
        closeLp.gravity = Gravity.RIGHT | Gravity.TOP;
        closeLp.topMargin = -dp(1);
        closeLp.rightMargin = -dp(1);
        stack.addView(close, closeLp);

        final PhotoAction action = new PhotoAction(date, mealKey, topName, arrayKey, title, close, rotate);
        action.itemView = stack;
        action.stackNames = new ArrayList<String>(group);
        action.stackChildViews = new ArrayList<View>(popped);
        action.stackChildViews.add(top);
        action.stackExpandedState = expanded;
        stack.setTag(action);

        View.OnClickListener toggle = new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                if (action.editing) {
                    return;
                }
                toggleMediaStack(stack, popped, badge, size, count, expanded);
            }
        };
        badge.setOnClickListener(toggle);
        stack.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                if (action.editing) {
                    return;
                }
                if (!expanded[0]) {
                    toggleMediaStack(stack, popped, badge, size, count, expanded);
                } else {
                    showPhotoViewer(date, mealKey, topName);
                }
            }
        });
        close.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                if (action.unstackGroup()) {
                    showGlassToast("已取消叠放", Toast.LENGTH_SHORT);
                }
            }
        });
        rotate.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                rotateMealMediaLeft(action);
            }
        });
        return stack;
    }

    private void toggleMediaStack(final FrameLayout stack, final List<View> popped, final TextView badge,
                                  final int size, final int count, final boolean[] expanded) {
        final boolean expand = !expanded[0];
        expanded[0] = expand;
        int gap = dp(spaceByLayout(8, 6, 5));
        int startWidth = stack.getWidth() > 0 ? stack.getWidth() : size;
        int endWidth = expand ? size * count + gap * (count - 1) : size;
        ValueAnimator animator = ValueAnimator.ofInt(startWidth, endWidth);
        animator.setDuration(expand ? 280 : 230);
        animator.setInterpolator(new android.view.animation.DecelerateInterpolator(1.55f));
        animator.addUpdateListener(new ValueAnimator.AnimatorUpdateListener() {
            @Override
            public void onAnimationUpdate(ValueAnimator animation) {
                ViewGroup.LayoutParams lp = stack.getLayoutParams();
                lp.width = (Integer) animation.getAnimatedValue();
                stack.setLayoutParams(lp);
            }
        });
        animator.start();

        for (int i = 0; i < popped.size(); i++) {
            final View child = popped.get(i);
            child.animate().cancel();
            if (expand) {
                child.setVisibility(View.VISIBLE);
                child.setAlpha(0f);
                child.setTranslationX(0f);
                child.setScaleX(0.86f);
                child.setScaleY(0.86f);
                child.animate()
                        .alpha(1f)
                        .translationX((i + 1) * (size + gap))
                        .scaleX(1f)
                        .scaleY(1f)
                        .setStartDelay(i * 24L)
                        .setDuration(280)
                        .setInterpolator(new android.view.animation.DecelerateInterpolator(1.45f))
                        .start();
            } else {
                child.animate()
                        .alpha(0f)
                        .translationX(0f)
                        .scaleX(0.86f)
                        .scaleY(0.86f)
                        .setStartDelay((popped.size() - i - 1) * 18L)
                        .setDuration(220)
                        .withEndAction(new Runnable() {
                            @Override
                            public void run() {
                                child.setVisibility(View.INVISIBLE);
                            }
                        })
                        .start();
            }
        }
        badge.setText(expand ? "↙" : "×" + count);
        badge.animate().cancel();
        badge.setScaleX(0.88f);
        badge.setScaleY(0.88f);
        badge.animate().scaleX(1f).scaleY(1f).setDuration(180).start();
    }

    private String mediaStackKey(String arrayKey) {
        return "photos".equals(arrayKey) ? "photoStacks" : "stickerStacks";
    }


    private boolean isMediaStacked(JSONObject meal, String arrayKey, String fileName) {
        JSONObject stacks = meal.optJSONObject(mediaStackKey(arrayKey));
        if (stacks == null || fileName == null) {
            return false;
        }
        if (stacks.has(fileName)) {
            return true;
        }
        JSONArray names = stacks.names();
        if (names != null) {
            for (int i = 0; i < names.length(); i++) {
                if (fileName.equals(stacks.optString(names.optString(i)))) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean stackMealMedia(String date, String mealKey, String arrayKey, String fileName,
                                   String targetName) {
        if (fileName == null || targetName == null || fileName.equals(targetName)) {
            return false;
        }
        JSONObject meal = optObj(ensureDay(date), mealKey);
        JSONArray old = meal.optJSONArray(arrayKey);
        if (old == null) {
            return false;
        }
        List<String> names = new ArrayList<String>();
        for (int i = 0; i < old.length(); i++) {
            String name = old.optString(i);
            if (name.length() > 0) {
                names.add(name);
            }
        }
        int sourceIndex = names.indexOf(fileName);
        int targetIndex = names.indexOf(targetName);
        if (sourceIndex < 0 || targetIndex < 0) {
            return false;
        }
        clearMediaStackRefs(meal, arrayKey, fileName);
        names.remove(sourceIndex);
        if (sourceIndex < targetIndex) {
            targetIndex--;
        }
        names.add(targetIndex + 1, fileName);
        JSONArray next = new JSONArray();
        for (String name : names) {
            next.put(name);
        }
        try {
            meal.put(arrayKey, next);
            JSONObject stacks = meal.optJSONObject(mediaStackKey(arrayKey));
            if (stacks == null) {
                stacks = new JSONObject();
                meal.put(mediaStackKey(arrayKey), stacks);
            }
            stacks.put(fileName, targetName);
            saveDays();
        } catch (JSONException ignored) {
            return false;
        }
        scheduleMediaRender(date);
        return true;
    }

    private boolean reorderMealMedia(String date, String mealKey, String arrayKey, String fileName,
                                     String targetName, boolean insertAfter) {
        if (fileName == null || targetName == null || fileName.equals(targetName)) {
            return false;
        }
        JSONObject meal = optObj(ensureDay(date), mealKey);
        JSONArray old = meal.optJSONArray(arrayKey);
        if (old == null) {
            return false;
        }
        List<String> names = new ArrayList<String>();
        for (int i = 0; i < old.length(); i++) {
            String name = old.optString(i);
            if (name.length() > 0) {
                names.add(name);
            }
        }
        List<String> original = new ArrayList<String>(names);
        int sourceIndex = names.indexOf(fileName);
        if (sourceIndex < 0 || !names.remove(fileName)) {
            return false;
        }
        int targetIndex = names.indexOf(targetName);
        if (targetIndex < 0) {
            return false;
        }
        int insertIndex = targetIndex + (insertAfter ? 1 : 0);
        names.add(Math.max(0, Math.min(insertIndex, names.size())), fileName);
        if (names.equals(original)) {
            return false;
        }
        clearMediaStackRefs(meal, arrayKey, fileName);
        JSONArray next = new JSONArray();
        for (String name : names) {
            next.put(name);
        }
        try {
            meal.put(arrayKey, next);
            saveDays();
        } catch (JSONException ignored) {
            return false;
        }
        scheduleMediaRender(date);
        return true;
    }

    private void scheduleMediaRender(final String date) {
        root.postDelayed(new Runnable() {
            @Override
            public void run() {
                if (inBookDetail) {
                    renderBookDetail(date);
                } else {
                    renderCurrent();
                }
            }
        }, 70);
    }

    private boolean unstackMealMedia(String date, String mealKey, String arrayKey, String fileName) {
        JSONObject meal = optObj(ensureDay(date), mealKey);
        clearMediaStackRefs(meal, arrayKey, fileName);
        saveDays();
        scheduleMediaRender(date);
        return true;
    }

    private boolean unstackMediaGroup(String date, String mealKey, String arrayKey, List<String> names) {
        if (names == null || names.size() <= 1) {
            return false;
        }
        JSONObject meal = optObj(ensureDay(date), mealKey);
        for (String name : names) {
            clearMediaStackRefs(meal, arrayKey, name);
        }
        saveDays();
        scheduleMediaRender(date);
        return true;
    }


    private void clearMediaStackRefs(JSONObject meal, String arrayKey, String fileName) {
        JSONObject stacks = meal.optJSONObject(mediaStackKey(arrayKey));
        if (stacks == null) {
            return;
        }
        stacks.remove(fileName);
        JSONArray names = stacks.names();
        if (names != null) {
            for (int i = 0; i < names.length(); i++) {
                String key = names.optString(i);
                if (fileName.equals(stacks.optString(key))) {
                    stacks.remove(key);
                }
            }
        }
        if (stacks.length() == 0) {
            meal.remove(mediaStackKey(arrayKey));
        }
    }





    private void rotateMealMediaLeft(final PhotoAction action) {
        if (action == null || action.rotating) {
            return;
        }
        if (action.foodId == null || action.foodId.isEmpty()) {
            JSONObject linked = NutritionStore.findByMedia(NutritionStore.meal(readJson(DATA_KEY), action.date, action.mealKey), action.fileName);
            if (linked != null) action.foodId = linked.optString("id");
        }
        if (action.foodId != null && !action.foodId.isEmpty()) {
            if (NutritionStore.rotateDisplayLeft(this, action.date, action.mealKey, action.foodId)) {
                days = readJson(DATA_KEY);
                JSONObject item = NutritionStore.find(NutritionStore.meal(days, action.date, action.mealKey), action.foodId);
                if (action.mediaContent instanceof TodayPaperView.RotatableMedia)
                    ((TodayPaperView.RotatableMedia) action.mediaContent).setMediaRotation(NutritionStore.displayRotation(item));
                else if (action.mediaContent instanceof ImageView)
                    action.mediaContent.setRotation(NutritionStore.displayRotation(item));
                else renderCurrent();
            } else showGlassToast("这张贴纸已移除，请刷新后重试", Toast.LENGTH_SHORT);
            return;
        }
        final File file = new File(getFilesDir(), action.fileName);
        if (!file.isFile()) {
            showGlassToast("图片不见了", Toast.LENGTH_SHORT);
            return;
        }
        action.rotating = true;
        if (action.rotateButton != null) {
            action.rotateButton.setEnabled(false);
            action.rotateButton.setAlpha(0.55f);
        }
        try {
            mediaThumbnailExecutor.execute(new Runnable() {
                @Override
                public void run() {
                    final boolean rotated = rotateMediaFileLeft(file);
                    runOnUiThread(new Runnable() {
                        @Override
                        public void run() {
                            action.rotating = false;
                            if (action.rotateButton != null) {
                                action.rotateButton.setEnabled(true);
                                action.rotateButton.setAlpha(1f);
                            }
                            if (!rotated) {
                                showGlassToast("旋转失败，请稍后重试", Toast.LENGTH_SHORT);
                                return;
                            }
                            refreshRotatedMediaPreview(action);
                            if (action.mediaContent instanceof TodayPaperView.RotatableMedia) renderCurrent();
                            if ("photos".equals(action.arrayKey)) FoodAnalysisJobService.enqueue(MainActivity.this, action.date, action.mealKey, action.fileName, true);
                        }
                    });
                }
            });
        } catch (java.util.concurrent.RejectedExecutionException ignored) {
            action.rotating = false;
            if (action.rotateButton != null) {
                action.rotateButton.setEnabled(true);
                action.rotateButton.setAlpha(1f);
            }
            showGlassToast("旋转失败，请稍后重试", Toast.LENGTH_SHORT);
        }
    }

    private void refreshRotatedMediaPreview(PhotoAction action) {
        if (action == null || action.itemView == null) {
            return;
        }
        refreshRotatedMediaPreview(action.itemView, action.fileName,
                new File(getFilesDir(), action.fileName).getAbsolutePath() + "@");
    }

    private void refreshRotatedMediaPreview(View view, String fileName, String cachePrefix) {
        if (view instanceof ImageView) {
            Object tag = view.getTag();
            if (tag instanceof String && ((String) tag).startsWith(cachePrefix)) {
                mediaThumbnailCache.remove((String) tag);
                int target = Math.max(dp(64), Math.max(view.getWidth(), view.getHeight()));
                loadMediaThumbnail((ImageView) view, fileName, target);
            }
            return;
        }
        if (view instanceof ViewGroup) {
            ViewGroup group = (ViewGroup) view;
            for (int i = 0; i < group.getChildCount(); i++) {
                refreshRotatedMediaPreview(group.getChildAt(i), fileName, cachePrefix);
            }
        }
    }

    private boolean rotateMediaFileLeft(File file) {
        Bitmap source = null;
        Bitmap rotated = null;
        File temp = new File(file.getParentFile(), file.getName() + ".rotate-tmp");
        try {
            source = decodeFileSampled(file, 2048);
            if (source == null) {
                return false;
            }
            Matrix matrix = new Matrix();
            matrix.postRotate(-90f);
            rotated = Bitmap.createBitmap(source, 0, 0,
                    source.getWidth(), source.getHeight(), matrix, true);
            if (file.getName().toLowerCase(Locale.US).endsWith(".png")) {
                savePng(rotated, temp);
            } else {
                saveBitmap(rotated, temp, 90);
            }
            java.nio.file.Files.move(temp.toPath(), file.toPath(),
                    java.nio.file.StandardCopyOption.REPLACE_EXISTING);
            return true;
        } catch (Exception error) {
            Log.e(LOG_TAG, "Unable to rotate media " + file.getName(), error);
            return false;
        } finally {
            if (temp.exists()) {
                temp.delete();
            }
            if (rotated != null && rotated != source && !rotated.isRecycled()) {
                rotated.recycle();
            }
            if (source != null && !source.isRecycled()) {
                source.recycle();
            }
        }
    }



