    private void deleteCloudAccount() {
        if (cloudDataSyncing) {
            showGlassToast("正在处理云端操作...", Toast.LENGTH_SHORT);
            return;
        }
        cloudDataSyncing = true;
        showGlassToast("正在注销云端账号...", Toast.LENGTH_SHORT);
        new Thread(new Runnable() {
            @Override
            public void run() {
                final CloudResult result = cloudDeleteAccountSync();
                runOnUiThread(new Runnable() {
                    @Override
                    public void run() {
                        cloudDataSyncing = false;
                        if (result.ok) {
                            clearCloudIdentity();
                            renderProfileSettingsPage();
                            showGlassToast("账号已注销，本机数据已保留", Toast.LENGTH_LONG);
                        } else {
                            showGlassToast(result.message.length() == 0 ? "注销失败，请稍后再试" : result.message, Toast.LENGTH_LONG);
                        }
                    }
                });
            }
        }).start();
    }

