            profile.put("cloudToken", "");
            profile.put("cloudWechatBound", false);
            profile.put("cloudHasPassword", false);
            profile.put("cloudCreatedAt", "");
            profile.put("cloudUpdatedAt", "");
            profile.put("cloudDataUpdatedAt", "");
            profile.put("cloudDataHash", "");
            profile.put("lastCloudBackupHash", "");
            profile.put("cloudAvatarUrl", "");
