    private void handleCloudSessionExpired() {
        clearCloudIdentity();
        if (inProfileSettingsPage) {
            renderProfileSettingsPage();
        } else if (inCloudSyncPage) {
            renderCloudSyncPage();
        } else if (inDataSecurityPage) {
            renderDataSecurityPage();
        } else {
            renderCurrentProfileHeaderIfNeeded();
        }
        showGlassToast("账号已在其他设备登录，本机已退出云端登录", Toast.LENGTH_LONG);
    }

