        private void drawMiniFlower(Canvas canvas, float x, float y, float size, int color) {
            paint.setStyle(Paint.Style.FILL);
            paint.setColor(color);
            for (int i = 0; i < 5; i++) {
                double angle = Math.PI * 2 * i / 5d - Math.PI / 2d;
                canvas.drawCircle(x + (float) Math.cos(angle) * size * 0.7f,
                        y + (float) Math.sin(angle) * size * 0.7f, size * 0.48f, paint);
            }
            paint.setColor(Color.rgb(255, 207, 73));
            canvas.drawCircle(x, y, size * 0.38f, paint);
        }

